const inlineBufferSecrets = parseEnvBlock(process.env.BUFFER_API_KEY || '');

function pickSecretValue(envValue, inlineValue, fileValue, key) {
  if (envValue && !envValue.includes('\n') && !envValue.startsWith(`${key}=`)) {
    return envValue.trim();
  }
  return inlineValue || fileValue || '';
}

