const createContactCommunicationsSQL = `
CREATE TABLE IF NOT EXISTS bna_contact_communications (
  id SERIAL PRIMARY KEY,
  contact_type TEXT NOT NULL DEFAULT 'lead' CHECK (contact_type IN ('lead', 'signup', 'student', 'general')),
  lead_id INTEGER REFERENCES bna_parent_leads(id) ON DELETE CASCADE,
  signup_id INTEGER REFERENCES signups(id) ON DELETE CASCADE,
  student_id INTEGER REFERENCES bna_students(id) ON DELETE SET NULL,
  channel TEXT NOT NULL DEFAULT 'internal_note' CHECK (channel IN ('whatsapp', 'phone', 'telegram', 'email', 'in_person', 'internal_note', 'other')),
  direction TEXT NOT NULL DEFAULT 'internal_note' CHECK (direction IN ('inbound', 'outbound', 'internal_note', 'meeting', 'call')),
  summary TEXT NOT NULL,
  body TEXT,
  follow_up_required BOOLEAN DEFAULT FALSE,
  occurred_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT DEFAULT 'Codex',
  source TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'telegram', 'ghl_import', 'dashboard', 'seed', 'wapi')),
  source_context JSONB DEFAULT '{}',
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CHECK (lead_id IS NOT NULL OR signup_id IS NOT NULL OR student_id IS NOT NULL OR contact_type = 'general')
);
`;

