async function ensureDefaultContentPrompts() {
  for (const [platform, config] of Object.entries(DEFAULT_CONTENT_PROMPTS)) {
    const result = await pool.query(
      `INSERT INTO bna_content_prompts (platform, label, prompt_text, version, updated_by)
       VALUES ($1, $2, $3, 1, 'system')
       ON CONFLICT (platform) DO NOTHING
       RETURNING *`,
      [platform, config.label, config.prompt_text]
    );
    let prompt = result.rows[0] || (await pool.query('SELECT * FROM bna_content_prompts WHERE platform = $1', [platform])).rows[0];
    const guardedPromptText = ensurePublicContentPromptGuardrails(prompt?.prompt_text, platform);
    if (
      prompt &&
      prompt.updated_by !== 'codex-brand-prompt-refresh' &&
      guardedPromptText !== String(prompt.prompt_text || '').trim()
    ) {
      prompt = (await pool.query(
        `UPDATE bna_content_prompts
         SET prompt_text = $2,
             version = COALESCE(version, 1) + 1,
             updated_by = 'system-public-content-guardrail',
             updated_at = NOW()
         WHERE id = $1
         RETURNING *`,
        [prompt.id, guardedPromptText]
      )).rows[0];
    }
    if (prompt) {
      await pool.query(
        `INSERT INTO bna_content_prompt_versions (prompt_id, version, prompt_text, change_note, updated_by)
         VALUES ($1, $2, $3, $4, $5)
         ON CONFLICT (prompt_id, version) DO NOTHING`,
        [prompt.id, prompt.version || 1, prompt.prompt_text, 'Initial/default prompt', prompt.updated_by || 'system']
      );
    }
  }
}

