function safeProviderStatus(value, fallback = 'draft') {
  const normalized = String(value || '').trim().toLowerCase();
  return PROVIDER_STATUS_VALUES.includes(normalized) ? normalized : fallback;
}

function safeCommercialModel(value, fallback = 'free_listing') {
  const normalized = String(value || '').trim().toLowerCase();
  return PROVIDER_COMMERCIAL_MODELS.includes(normalized) ? normalized : fallback;
}

function providerPlanForCommercialModel(commercialModel) {
  const model = safeCommercialModel(commercialModel);
  if (['paid_setup', 'monthly_management'].includes(model)) return 'managed_provider';
  if (model === 'school_subscription') return 'school_workspace';
  if (['revenue_share', 'custom'].includes(model)) return 'revenue_share_partner';
  return 'free_listing';
}

function safeProviderPlan(value, commercialModel = 'free_listing') {
  const normalized = String(value || '').trim().toLowerCase();
  return PROVIDER_PLAN_DEFINITIONS[normalized] ? normalized : providerPlanForCommercialModel(commercialModel);
}

function safeProviderSourceOfTruth(value, fallback = 'unknown_pending_access') {
  const normalized = String(value || '').trim().toLowerCase();
  return PROVIDER_SOURCE_OF_TRUTH_VALUES.includes(normalized) ? normalized : fallback;
}

function safeProviderIntegrationStatus(value, fallback = 'no_access') {
  const normalized = String(value || '').trim().toLowerCase();
  return PROVIDER_INTEGRATION_STATUS_VALUES.includes(normalized) ? normalized : fallback;
}

function providerEntitlementRowsForPlan(planKey = 'free_listing') {
  const plan = PROVIDER_PLAN_DEFINITIONS[planKey] || PROVIDER_PLAN_DEFINITIONS.free_listing;
  const enabled = new Set(plan.enabled || []);
  return PROVIDER_ENTITLEMENT_ROWS.map(([key, label]) => ({
    key,
    label,
    enabled: enabled.has(key),
    included_in_plan: enabled.has(key),
    status: enabled.has(key) ? 'included' : 'upgrade_available',
  }));
}

function providerPlansView() {
  return Object.entries(PROVIDER_PLAN_DEFINITIONS).map(([key, plan]) => ({
    key,
    label: plan.label,
    helper: plan.helper,
    commercial_models: plan.commercial_models,
    entitlements: providerEntitlementRowsForPlan(key),
  }));
}

function providerPublicCta(provider = {}) {
  const model = safeCommercialModel(provider.commercial_model);
  if (model === 'school_subscription') return { primary: 'Apply', secondary: 'Contact School', tertiary: 'Parent Portal' };
  if (model === 'revenue_share' || model === 'custom') return { primary: 'Join Membership', secondary: 'Request Info' };
  if (model === 'paid_setup' || model === 'monthly_management') return { primary: 'Signup', secondary: 'Request Info', tertiary: 'View Program' };
  return { primary: 'Request Info', secondary: 'Contact', tertiary: provider.claim_listing_enabled === false ? '' : 'Claim This Listing' };
}

async function seedProviderCommercialRows(provider, {
  planKey = provider?.entitlement_plan || providerPlanForCommercialModel(provider?.commercial_model),
  externalSystem = null,
  accessStatus = 'needed',
  db = pool,
} = {}) {
  if (!provider?.id) return;
  const plan = safeProviderPlan(planKey, provider.commercial_model);
  for (const item of providerEntitlementRowsForPlan(plan)) {
    await db.query(
      `INSERT INTO bna_provider_entitlements (
         provider_id, entitlement_key, entitlement_group, enabled, included_in_plan, status, notes, metadata
       ) VALUES ($1, $2, 'provider_commercial_model', $3, $4, $5, $6, $7::jsonb)
       ON CONFLICT (provider_id, entitlement_key) DO UPDATE SET
         enabled = EXCLUDED.enabled,
         included_in_plan = EXCLUDED.included_in_plan,
         status = EXCLUDED.status,
         updated_at = NOW()`,
      [
        provider.id,
        item.key,
        item.enabled,
        item.included_in_plan,
        item.status,
        item.enabled ? 'Included in current provider plan.' : 'Available as an upgrade; do not show as active.',
        JSON.stringify({ plan }),
      ]
    );
  }

  await db.query(
    `INSERT INTO bna_provider_integrations (
       provider_id, integration_key, label, external_system, source_of_truth, integration_status, notes, metadata
     ) VALUES ($1, 'external_delivery_system', 'External delivery system', $2, $3, $4, $5, $6::jsonb)
     ON CONFLICT (provider_id, integration_key) DO UPDATE SET
       external_system = EXCLUDED.external_system,
       source_of_truth = EXCLUDED.source_of_truth,
       integration_status = EXCLUDED.integration_status,
       notes = EXCLUDED.notes,
       updated_at = NOW()`,
    [
      provider.id,
      externalSystem || 'None configured',
      safeProviderSourceOfTruth(provider.source_of_truth),
      safeProviderIntegrationStatus(provider.integration_status),
      externalSystem ? 'External system is tracked as delivery until inspected.' : 'No external app access configured yet.',
      JSON.stringify({ plan }),
    ]
  );

  const checklistOverrides = {
    rabbi_contact_email: {
      status: 'needed',
      next_action: 'Ask Rabbi Elie for the best email address in WhatsApp before sending any scoped login.',
      notes: 'Login information must stay held until email is stored on the provider/project member record.',
    },
    rabbi_whatsapp_phone: {
      status: 'needed',
      next_action: 'Confirm the WhatsApp/contact phone before using manual links or login handoff.',
      notes: 'Do not assume the operator test chat ID or any old phone belongs to Rabbi Elie.',
    },
    scoped_login_username: {
      status: 'needed',
      next_action: 'Confirm the scoped One Time username on the provider/project member record before sending credentials.',
      notes: 'The generated ops secret can exist before handoff, but login is not sent until Drive/social setup and contact fields are ready.',
    },
    login_release_guard: {
      status: 'needed',
      next_action: 'Release login only after Drive/social ingestion is mapped and Shloimie confirms the platform settings.',
      notes: 'Send scoped login last, after setup readiness and contact collection are complete.',
    },
    one_time_drive_video_drop: {
      status: 'requested',
      next_action: 'Use the One Time Mishnah Class Drive root and mapped video-drop lane for Rabbi media intake.',
      notes: 'This must stay separate from BNA school raw media intake.',
    },
    one_time_social_output_map: {
      status: 'needed',
      next_action: 'Configure Facebook, LinkedIn, YouTube, Instagram, and WhatsApp Status destinations before social writes.',
      notes: 'Text drafts and media uploads stay approval-gated; publishing now always needs separate approval.',
    },
  };
  for (const [itemKey, label] of PROVIDER_ACCESS_CHECKLIST_SEED) {
    const override = checklistOverrides[itemKey] || {};
    await db.query(
      `INSERT INTO bna_provider_access_checklist (
         provider_id, item_key, label, status, owner, next_action, notes, metadata
       ) VALUES ($1, $2, $3, $4, 'Shloimie', $5, $6, $7::jsonb)
       ON CONFLICT (provider_id, item_key) DO NOTHING`,
      [
        provider.id,
        itemKey,
        label,
        override.status || accessStatus,
        override.next_action || 'Request or confirm access before enabling sync/import automation.',
        override.notes || 'Pre-integration checklist item.',
        JSON.stringify({ plan }),
      ]
    );
  }
}

