async function getProviderPortalPayload(providerId, db = pool) {
  const provider = (await db.query(
    `SELECT id, display_name, provider_name, category, short_description, full_description,
            city, neighborhood, address, service_area,
            contact_name, contact_email, contact_phone, whatsapp_phone,
            website_url, google_business_profile_url, google_place_id, profile_image_url,
            login_username, status, provider_status, commercial_model, entitlement_plan,
            source_of_truth, integration_status, setup_package, managed_services,
            public_listing_enabled, public_signup_enabled, claim_listing_enabled,
            can_receive_messages, can_advertise,
            internal_owner, public_notes, marketing_management_enabled,
            billing_management_enabled, admin_fee_notes, approved_at, last_login_at, updated_at
     FROM bna_service_providers
     WHERE id = $1`,
    [providerId]
  )).rows[0] || null;
  if (!provider) return null;

  const services = (await db.query(
    `SELECT
       s.*,
       COALESCE((
         SELECT json_agg(sess.* ORDER BY sess.start_time NULLS LAST, sess.id)
         FROM bna_provider_service_sessions sess
         WHERE sess.service_id = s.id AND sess.status <> 'archived'
       ), '[]'::json) AS sessions,
       COALESCE((
         SELECT json_agg(link.* ORDER BY link.id)
         FROM bna_provider_rabbi_links link
         WHERE link.service_id = s.id AND link.status <> 'archived'
       ), '[]'::json) AS rabbi_links
     FROM bna_provider_services s
     WHERE s.provider_id = $1
       AND s.status <> 'archived'
     ORDER BY s.updated_at DESC, s.id DESC`,
    [providerId]
  )).rows;

  return {
    provider: providerAccountView(provider),
    services,
    plans: providerPlansView(),
    entitlements: (await db.query(
      `SELECT *
       FROM bna_provider_entitlements
       WHERE provider_id = $1
       ORDER BY entitlement_key`,
      [providerId]
    )).rows,
    integrations: (await db.query(
      `SELECT *
       FROM bna_provider_integrations
       WHERE provider_id = $1
       ORDER BY integration_key`,
      [providerId]
    )).rows,
    access_checklist: (await db.query(
      `SELECT *
       FROM bna_provider_access_checklist
       WHERE provider_id = $1
       ORDER BY item_key`,
      [providerId]
    )).rows,
    messages: (await db.query(
      `SELECT id, provider_id, service_id, parent_email, student_id, direction, channel,
              subject, body, status, source, metadata, created_at, updated_at
       FROM bna_provider_messages
       WHERE provider_id = $1
         AND status <> 'archived'
       ORDER BY created_at DESC, id DESC
       LIMIT 80`,
      [providerId]
    )).rows,
    guardrails: {
      review_required: true,
      public_changes: 'Provider profile and service edits stay pending_review until BNA approves them.',
      billing: 'No live billing, charge, payout, or admin-fee automation is enabled from the provider portal.',
      visibility: 'Provider login is scoped to this provider record only.',
      entitlements: 'Visible features are controlled by the provider commercial plan. Upgrade-only features stay disabled until BNA changes the plan.',
    },
  };
}

function numericOrNull(value) {
  if (value === undefined || value === null || value === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function providerPublicProfileFieldsFromBody(body = {}) {
  const direct = (key, max = 220) => limitText(body[key] || body[toCamelCaseKey(key)], max) || null;
  const has = (key) => Object.prototype.hasOwnProperty.call(body, key) || Object.prototype.hasOwnProperty.call(body, toCamelCaseKey(key));
  return {
    display_name: direct('display_name', 160),
    category: limitText(body.category || body.service_type || body.serviceType, 120) || null,
    short_description: direct('short_description', 320),
    full_description: direct('full_description', 1600),
    city: limitText(body.city || body.location, 120) || null,
    neighborhood: direct('neighborhood', 120),
    address: direct('address', 220),
    service_area: limitText(body.service_area || body.serviceArea || body.location, 220) || null,
    whatsapp_phone: limitText(body.whatsapp_phone || body.whatsappPhone || body.whatsapp || body.phone, 80) || null,
    website_url: limitText(body.website_url || body.websiteUrl || body.website, 420) || null,
    google_business_profile_url: limitText(body.google_business_profile_url || body.googleBusinessProfileUrl || body.google_url || body.googleUrl, 520) || null,
    google_place_id: limitText(body.google_place_id || body.googlePlaceId || body.place_id || body.placeId, 220) || null,
    profile_image_url: limitText(body.profile_image_url || body.profileImageUrl || body.image_url || body.imageUrl, 520) || null,
    can_receive_messages: has('can_receive_messages') ? Boolean(body.can_receive_messages ?? body.canReceiveMessages) : null,
    can_advertise: has('can_advertise') ? Boolean(body.can_advertise ?? body.canAdvertise) : null,
  };
}

function toCamelCaseKey(key) {
  return String(key || '').replace(/_([a-z])/g, (_, char) => char.toUpperCase());
}

async function updateProviderPublicProfileFields(providerId, body = {}, db = pool) {
  const profileFields = providerPublicProfileFieldsFromBody(body);
  const fields = [];
  const values = [];
  for (const [key, value] of Object.entries(profileFields)) {
    if (value === null || value === undefined) continue;
    values.push(value);
    fields.push(`${key} = $${values.length}`);
  }
  if (!fields.length) return null;
  values.push(providerId);
  const result = await db.query(
    `UPDATE bna_service_providers
     SET ${fields.join(', ')},
         updated_at = NOW()
     WHERE id = $${values.length}
     RETURNING *`,
    values
  );
  return result.rows[0] || null;
}

function uniqueStrings(items = []) {
  return [...new Set(items.map((item) => String(item || '').trim()).filter(Boolean))];
}

function providerIntakeCategoryFromText(text = '') {
  const lower = text.toLowerCase();
  const matches = [
    [/mishn(a|ah)|torah|gemara|rebbe|rabbi|limudei|kodesh/, 'Torah learning'],
    [/math|algebra|english|tutor|tutoring|homework/, 'Tutoring'],
    [/therapy|therapist|ot|speech|emotional|coach|coaching/, 'Therapy / coaching'],
    [/electronics|robotics|coding|computer|stem/, 'Skills group'],
    [/sport|fitness|movement|karate|swim|gym/, 'Movement / activity'],
  ].find(([regex]) => regex.test(lower));
  return matches ? matches[1] : '';
}

function parseProviderIntakeText(rawText = '') {
  const text = String(rawText || '').trim();
  const compact = text.replace(/\s+/g, ' ');
  const urls = uniqueStrings(compact.match(/https?:\/\/[^\s<>"')]+/gi) || []);
  const email = normalizeEmail((compact.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i) || [])[0]);
  const phone = (compact.match(/(?:\+?\d[\d\s().-]{6,}\d)/) || [])[0]?.replace(/\s+/g, ' ').trim() || '';
  const googleUrl = urls.find((url) => /google|maps\.app\.goo\.gl|goo\.gl\/maps|place_id/i.test(url)) || '';
  const websiteUrl = urls.find((url) => url !== googleUrl && !/wa\.me|whatsapp/i.test(url)) || '';
  const waUrl = urls.find((url) => /wa\.me|whatsapp/i.test(url)) || '';
  const category = providerIntakeCategoryFromText(text);
  const city = (compact.match(/\b(Beit Shemesh|Ramat Beit Shemesh|Jerusalem|Yerushalayim|Online|Zoom)\b/i) || [])[0] || '';
  const nameHint = compact.match(/(?:provider|business|program|service|class)\s*(?:name)?\s*[:\-]\s*([^.;\n]{3,80})/i)?.[1] || '';
  const placeId = compact.match(/\bplace[_\s-]?id\s*[:=]\s*([A-Za-z0-9_-]{10,220})/i)?.[1] || '';
  const fields = {};
  if (nameHint) fields.display_name = limitText(nameHint, 160);
  if (category) fields.category = category;
  if (city) fields.city = city;
  if (email) fields.email = email;
  if (phone) fields.phone = phone;
  if (phone || waUrl) fields.whatsapp_phone = phone || waUrl;
  if (websiteUrl) fields.website_url = websiteUrl;
  if (googleUrl) fields.google_business_profile_url = googleUrl;
  if (placeId) fields.google_place_id = placeId;
  if (compact) fields.short_description = limitText(compact.split(/(?<=[.!?])\s+/)[0] || compact, 320);

  const openQuestions = [];
  if (!fields.display_name) openQuestions.push('What public provider or program name should appear in the directory?');
  if (!fields.category) openQuestions.push('Which category should parents use to find this provider?');
  if (!fields.city && !/online/i.test(compact)) openQuestions.push('What city, neighborhood, or service area should be shown?');
  if (!fields.phone && !fields.email && !fields.website_url) openQuestions.push('What public contact method should parents use?');
  if (!fields.google_business_profile_url && !fields.google_place_id) openQuestions.push('Is there a Google Business Profile or Google Maps Place link for indexing?');

  const setupTasks = [
    'Review extracted provider profile fields before public publishing.',
    fields.google_business_profile_url || fields.google_place_id
      ? 'Verify the Google Business/Profile link and store the exact Place ID if available.'
      : 'Ask provider for Google Maps/Profile URL or Place ID if they have one.',
    fields.website_url ? 'Check website link before making the listing active.' : '',
    'Confirm whether this is free listing only or paid managed setup.',
  ].filter(Boolean);

  const confidence = Math.min(0.95, 0.25 + Object.keys(fields).length * 0.1);
  return {
    parsed_fields: fields,
    open_questions: openQuestions,
    setup_tasks: setupTasks,
    confidence,
  };
}

async function createProviderIntakeRecord({ providerId = null, sessionKey = '', rawText = '', source = 'natural_language', fileUrl = '', metadata = {} } = {}, db = pool) {
  const text = limitText(rawText, 12000) || '';
  if (!text && !fileUrl) {
    const error = new Error('raw_text or file_url is required for provider intake');
    error.statusCode = 400;
    throw error;
  }
  const parsed = parseProviderIntakeText(text);
  const key = limitText(sessionKey, 120) || `provider-intake-${generateSecureToken(12)}`;
  const status = parsed.open_questions.length ? 'needs_review' : 'parsed';
  const session = (await db.query(
    `INSERT INTO bna_provider_onboarding_sessions (
       provider_id, session_key, status, current_step, proposed_fields,
       open_questions, setup_tasks, metadata
     ) VALUES ($1, $2, $3, 'review', $4::jsonb, $5::jsonb, $6::jsonb, $7::jsonb)
     ON CONFLICT (session_key) DO UPDATE
       SET provider_id = COALESCE(EXCLUDED.provider_id, bna_provider_onboarding_sessions.provider_id),
           status = EXCLUDED.status,
           proposed_fields = EXCLUDED.proposed_fields,
           open_questions = EXCLUDED.open_questions,
           setup_tasks = EXCLUDED.setup_tasks,
           metadata = bna_provider_onboarding_sessions.metadata || EXCLUDED.metadata,
           updated_at = NOW()
     RETURNING *`,
    [
      providerId || null,
      key,
      status,
      JSON.stringify(parsed.parsed_fields),
      JSON.stringify(parsed.open_questions),
      JSON.stringify(parsed.setup_tasks),
      JSON.stringify(metadata || {}),
    ]
  )).rows[0];
  const record = (await db.query(
    `INSERT INTO bna_provider_intake_records (
       session_id, provider_id, source, raw_text, file_url, parsed_fields,
       open_questions, setup_tasks, confidence, status, metadata
     ) VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7::jsonb, $8::jsonb, $9, $10, $11::jsonb)
     RETURNING *`,
    [
      session.id,
      providerId || null,
      ['natural_language', 'provider_form', 'paste', 'upload', 'admin', 'api'].includes(source) ? source : 'natural_language',
      text || null,
      limitText(fileUrl, 520) || null,
      JSON.stringify(parsed.parsed_fields),
      JSON.stringify(parsed.open_questions),
      JSON.stringify(parsed.setup_tasks),
      parsed.confidence,
      status,
      JSON.stringify(metadata || {}),
    ]
  )).rows[0];
  return {
    session,
    intake: record,
    ...parsed,
  };
}

