// GHL Helper Functions
async function ghlRequest(endpoint, options = {}) {
  const url = `${GHL_API_BASE}${endpoint}`;
  const response = await fetch(url, {
    ...options,
    headers: {
      'Authorization': `Bearer ${GHL_PIT_TOKEN}`,
      'Content-Type': 'application/json',
      'Version': GHL_API_VERSION,
      ...options.headers
    }
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`GHL API error: ${response.status} - ${error}`);
  }

  return response.json();
}

async function ghlSocialRequest(endpoint, options = {}) {
  if (!GHL_PIT_TOKEN) throw new Error('GHL_PIT_TOKEN not configured');
  const response = await fetch(`${GHL_API_BASE}${endpoint}`, {
    ...options,
    headers: {
      'Authorization': `Bearer ${GHL_PIT_TOKEN}`,
      'Accept': 'application/json',
      'Version': GHL_SOCIAL_API_VERSION,
      ...options.headers
    }
  });

  if (!response.ok) {
    const error = await response.text();
    const socialError = new Error(`GHL social API error: ${response.status} - ${error}`);
    socialError.status = response.status;
    socialError.endpoint = endpoint;
    socialError.body = error;
    socialError.hint = ghlSocialErrorHint(response.status, error);
    throw socialError;
  }

  if (response.status === 204) return null;
  const contentType = response.headers.get('content-type') || '';
  return contentType.includes('application/json') ? response.json() : response.text();
}

function ghlSocialErrorHint(status, body = '') {
  const text = String(body || '').toLowerCase();
  if (status === 401 && text.includes('command timed out')) {
    return 'GHL can read Social Planner data, but create-post is being refused. Recreate or edit the BNA sub-account Private Integration Token with the Social Planner post.write scope enabled.';
  }
  if (status === 401) {
    return 'Check that the token is a BNA sub-account Private Integration Token and includes Social Planner permissions for this location.';
  }
  if (status === 422) {
    return 'GHL reached the Social Planner API, but rejected the request shape. Check accountIds, type, status, summary, and media fields.';
  }
  return 'Check the GHL Social Planner token permissions and connected social account status.';
}

async function listGhlSocialAccounts() {
  const data = await ghlSocialRequest(`/social-media-posting/${GHL_LOCATION_ID}/accounts`);
  return data?.results?.accounts || [];
}

async function listGhlSocialPosts({ type = 'all', limit = 10 } = {}) {
  const data = await ghlSocialRequest(`/social-media-posting/${GHL_LOCATION_ID}/posts/list`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ limit: String(limit), type }),
  });
  return data?.results?.posts || data?.posts || [];
}

function normalizeGhlPostText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

async function findRecentGhlPostForContent({ accountId, summary, publishNow }) {
  const expectedSummary = normalizeGhlPostText(summary);
  const expectedStatus = publishNow ? 'published' : 'draft';
  const posts = await listGhlSocialPosts({ type: publishNow ? 'published' : 'all', limit: 20 });
  return posts.find((post) => {
    const postSummary = normalizeGhlPostText(post.summary);
    const accountMatches = Array.isArray(post.accountIds)
      ? post.accountIds.some((id) => String(id) === String(accountId))
      : false;
    const statusMatches = String(post.status || '').toLowerCase() === expectedStatus;
    const summaryMatches = postSummary === expectedSummary
      || postSummary.startsWith(expectedSummary.slice(0, 180))
      || expectedSummary.startsWith(postSummary.slice(0, 180));
    return accountMatches && statusMatches && summaryMatches;
  }) || null;
}

function usableSocialAccountsForPlatform(accounts, platform) {
  const requestedPlatform = String(platform || '').toLowerCase();
  return (accounts || []).filter((account) =>
    String(account.platform || '').toLowerCase() === requestedPlatform
    && !account.isExpired
    && !account.deleted
    && account.id
  );
}

function resolveGhlFacebookAccount(accounts) {
  const facebookAccounts = usableSocialAccountsForPlatform(accounts, 'facebook');
  if (!facebookAccounts.length) {
    const error = new Error('No active connected Facebook account found in GHL');
    error.status = 409;
    error.hint = 'Connect or refresh the BNA Facebook account in GHL Social Planner.';
    throw error;
  }

  if (GHL_DEFAULT_FACEBOOK_ACCOUNT_ID) {
    const configured = facebookAccounts.find((account) => String(account.id) === String(GHL_DEFAULT_FACEBOOK_ACCOUNT_ID));
    if (configured) return configured;
    const error = new Error('Configured GHL_DEFAULT_FACEBOOK_ACCOUNT_ID does not match an active Facebook account');
    error.status = 409;
    error.hint = 'Run /accounts, copy the intended Facebook account id, and update GHL_DEFAULT_FACEBOOK_ACCOUNT_ID.';
    throw error;
  }

  if (facebookAccounts.length === 1) return facebookAccounts[0];

  const error = new Error('Multiple active Facebook accounts are connected; refusing to pick one automatically');
  error.status = 409;
  error.hint = 'Set GHL_DEFAULT_FACEBOOK_ACCOUNT_ID to the approved BNA Facebook account before creating GHL drafts from Content.';
  throw error;
}

async function getDefaultGhlUserId() {
  const data = await ghlSocialRequest(`/users/?locationId=${encodeURIComponent(GHL_LOCATION_ID)}`);
  const userId = data?.users?.[0]?.id;
  if (!userId) throw new Error('No GHL user found for this location');
  return userId;
}

async function uploadLocalFileToGhlSocial(filePath, options = {}) {
  const fileBuffer = fs.readFileSync(filePath);
  const filename = options.filename || path.basename(filePath);
  const mimeType = options.mimeType || 'application/octet-stream';
  const form = new FormData();

  form.append('locationId', GHL_LOCATION_ID);
  form.append('hosted', 'false');
  form.append('name', filename);
  form.append('file', new Blob([fileBuffer], { type: mimeType }), filename);

  const response = await fetch(`${GHL_API_BASE}/medias/upload-file`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${GHL_PIT_TOKEN}`,
      'Version': GHL_SOCIAL_API_VERSION,
    },
    body: form,
  });

  if (!response.ok) {
    const error = await response.text();
    throw new Error(`GHL media upload failed: ${response.status} - ${error}`);
  }

  return response.json();
}

function socialPostTypeForMedia(mediaItems) {
  return mediaItems.some((item) => String(item.type || '').startsWith('video/')) ? 'reel' : 'post';
}

function shouldPublishFacebookAfterApproval(output) {
  const metadata = safeJsonParse(output?.metadata);
  return Boolean(
    metadata.publish_after_approval
    || metadata.facebook_publish_after_approval
    || metadata.ghl_publish_mode === 'published'
    || metadata.ghl_status_after_approval === 'published'
  );
}

function postReadyMediaUrlFromContent(job, outputMetadata) {
  const explicitUrl =
    outputMetadata.attached_media_url
    || outputMetadata.ghl_media_url
    || outputMetadata.post_ready_media_url
    || '';
  if (explicitUrl) return explicitUrl;

  const jobUrl = String(job?.media_url || '').trim();
  if (!jobUrl || !outputMetadata.media_url_is_post_ready) return '';
  return jobUrl;
}

async function buildFacebookMediaItemsFromContent(job, output, outputMetadata) {
  const media = [];
  const localPath = job?.local_path ? path.resolve(__dirname, job.local_path) : '';
  const mimeType = String(
    outputMetadata.attached_media_mime_type
    || outputMetadata.ghl_media_mime_type
    || job?.mime_type
    || ''
  ).toLowerCase();

  if (mimeType.startsWith('audio/')) return media;

  if (localPath && fs.existsSync(localPath)) {
    const uploaded = await uploadLocalFileToGhlSocial(localPath, {
      filename: path.basename(localPath),
      mimeType: job.mime_type || 'application/octet-stream',
    });
    if (uploaded?.url) {
      media.push({
        url: uploaded.url,
        type: job.mime_type || 'application/octet-stream',
        caption: '',
      });
    }
    return media;
  }

  const mediaUrl = postReadyMediaUrlFromContent(job, outputMetadata);
  if (mediaUrl) {
    media.push({
      url: mediaUrl,
      type: outputMetadata.attached_media_mime_type || outputMetadata.ghl_media_mime_type || job?.mime_type || 'application/octet-stream',
      caption: '',
    });
  }

  return media;
}

async function createFacebookDraftFromContent(job, output, options = {}) {
  const accounts = await listGhlSocialAccounts();
  const facebook = resolveGhlFacebookAccount(accounts);
  const outputMetadata = safeJsonParse(output?.metadata);
  const publishNow = Boolean(options.publishNow);

  const media = await buildFacebookMediaItemsFromContent(job, output, outputMetadata);

  const userId = await getDefaultGhlUserId();
  const created = await ghlSocialRequest(`/social-media-posting/${GHL_LOCATION_ID}/posts`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        accountIds: [facebook.id],
        userId,
        summary: output.body || '',
        media,
        type: socialPostTypeForMedia(media),
      status: publishNow ? 'published' : 'draft',
    }),
  });
  const post = created?.results?.post || await findRecentGhlPostForContent({
    accountId: facebook.id,
    summary: output.body || '',
    publishNow,
  }).catch(() => null);

  return { account: facebook, media, created, post, publishNow };
}

let cachedBufferOrganizations = null;
let cachedBufferChannels = null;

function isBufferSocialOutputType(outputType) {
  return ['facebook_post', 'linkedin_post', 'youtube_description'].includes(String(outputType || ''));
}

function bufferServiceForOutputType(outputType) {
  return ({
    facebook_post: 'facebook',
    linkedin_post: 'linkedin',
    youtube_description: 'youtube',
  })[outputType] || '';
}

async function bufferGraphql(query, variables = {}) {
  if (!BUFFER_API_KEY) {
    const error = new Error('BUFFER_API_KEY is not configured');
    error.status = 503;
    error.hint = 'Add BUFFER_API_KEY in Railway and local .secrets/buffer-api-key.txt.';
    throw error;
  }

  const response = await fetch(BUFFER_API_BASE, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${BUFFER_API_KEY}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ query, variables }),
  });

  const text = await response.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : {};
  } catch {
    data = { raw: text };
  }

  if (!response.ok || data.errors) {
    const error = new Error(
      data.errors?.map((item) => item.message).filter(Boolean).join('; ')
      || data.raw
      || `Buffer API error: ${response.status}`
    );
    error.status = response.status || 500;
    error.body = JSON.stringify(data).slice(0, 1000);
    error.hint = response.status === 401
      ? 'Check that BUFFER_API_KEY is valid and has posts/channel access.'
      : 'Check the Buffer channel IDs and API permissions.';
    throw error;
  }

  return data.data || {};
}

async function listBufferOrganizations() {
  if (cachedBufferOrganizations) return cachedBufferOrganizations;
  const data = await bufferGraphql(`
    query GetOrganizations {
      account {
        organizations {
          id
          name
          ownerEmail
        }
      }
    }
  `);
  cachedBufferOrganizations = data.account?.organizations || [];
  return cachedBufferOrganizations;
}

async function listBufferChannels() {
  if (cachedBufferChannels) return cachedBufferChannels;
  const organizationIds = BUFFER_ORGANIZATION_ID
    ? [BUFFER_ORGANIZATION_ID]
    : (await listBufferOrganizations()).map((organization) => organization.id).filter(Boolean);
  const allChannels = [];

  for (const organizationId of organizationIds) {
    const data = await bufferGraphql(`
      query GetChannels($organizationId: OrganizationId!) {
        channels(input: { organizationId: $organizationId, filter: { isLocked: false } }) {
          id
          name
          displayName
          service
          avatar
          isQueuePaused
        }
      }
    `, { organizationId });
    allChannels.push(...(data.channels || []).map((channel) => ({ ...channel, organizationId })));
  }

  cachedBufferChannels = allChannels;
  return cachedBufferChannels;
}

async function resolveBufferChannel(outputType) {
  const configuredId = BUFFER_CHANNEL_IDS[outputType];
  const service = bufferServiceForOutputType(outputType);
  const channels = await listBufferChannels();

  if (configuredId) {
    const configured = channels.find((channel) => String(channel.id) === String(configuredId));
    if (configured) return configured;
    const error = new Error(`Configured Buffer channel id for ${outputType} was not found in connected channels`);
    error.status = 409;
    error.hint = 'Check BUFFER_FACEBOOK_CHANNEL_ID, BUFFER_LINKEDIN_CHANNEL_ID, and BUFFER_YOUTUBE_CHANNEL_ID in Railway.';
    throw error;
  }

  const matches = channels.filter((channel) => String(channel.service || '').toLowerCase() === service);
  if (matches.length === 1) return matches[0];
  const error = new Error(matches.length
    ? `Multiple Buffer ${service} channels found; configure the channel id explicitly`
    : `No Buffer ${service} channel found`);
  error.status = 409;
  error.hint = `Set BUFFER_${service.toUpperCase()}_CHANNEL_ID in Railway.`;
  throw error;
}

async function createBufferPostFromContent(job, output, options = {}) {
  if (!isBufferSocialOutputType(output.output_type)) {
    throw new Error(`${output.output_type || 'This output'} is not a Buffer social output type`);
  }

  const text = String(output.body || '').trim();
  if (!text) {
    const error = new Error(`${outputTypeLabel(output.output_type)} has no text to send to Buffer`);
    error.status = 400;
    throw error;
  }

  const channel = await resolveBufferChannel(output.output_type);
  const publishNow = Boolean(options.publishNow);
  const mode = publishNow ? 'shareNow' : 'addToQueue';
  const saveToDraft = !publishNow;
  const data = await bufferGraphql(`
    mutation CreateBufferPost($text: String!, $channelId: ChannelId!, $saveToDraft: Boolean!) {
      createPost(input: {
        text: $text
        channelId: $channelId
        schedulingType: automatic
        mode: ${mode}
        saveToDraft: $saveToDraft
      }) {
        ... on PostActionSuccess {
          post {
            id
            text
            status
            channel {
              id
              service
              displayName
            }
          }
        }
        ... on MutationError {
          message
        }
      }
    }
  `, { text, channelId: channel.id, saveToDraft });

  const result = data.createPost;
  if (result?.message && !result?.post) {
    const error = new Error(result.message);
    error.status = 422;
    error.hint = 'Buffer rejected the post mutation. Check whether the channel supports this post type and whether media is required.';
    throw error;
  }

  if (!result?.post?.id) {
    const error = new Error('Buffer did not return a created post id');
    error.status = 502;
    error.body = JSON.stringify(data).slice(0, 1000);
    throw error;
  }

  return {
    provider: 'buffer',
    publishNow,
    channel,
    created: result,
    post: result.post,
    media: [],
  };
}

function outputTypeLabel(outputType) {
  return ({
    whatsapp_update: 'WhatsApp update',
    facebook_post: 'Facebook post',
    weekly_newsletter: 'weekly newsletter',
    linkedin_post: 'LinkedIn post',
    youtube_description: 'YouTube description',
    google_business_post: 'Google Business post',
    blog_draft: 'website blog',
    daily_report: 'daily report',
    parent_email: 'parent email',
    teaching_philosophy_note: 'teaching philosophy note',
    short_clip: 'short clip packaging',
  })[outputType] || outputType;
}

function platformForOutputType(outputType) {
  return ({
    whatsapp_update: 'whatsapp',
    facebook_post: 'facebook',
    weekly_newsletter: 'email',
    linkedin_post: 'linkedin',
    youtube_description: 'youtube',
    google_business_post: 'google_business',
    blog_draft: 'website',
    daily_report: 'internal',
    parent_email: 'email',
    teaching_philosophy_note: 'teaching_philosophy',
    short_clip: 'short_clip',
  })[outputType] || null;
}

function parseOutputType(value) {
  if (!value) return null;
  const aliases = {
    whatsapp: 'whatsapp_update',
    facebook: 'facebook_post',
    newsletter: 'weekly_newsletter',
    linkedin: 'linkedin_post',
    youtube: 'youtube_description',
    google: 'google_business_post',
    google_business: 'google_business_post',
    gbp: 'google_business_post',
    blog: 'blog_draft',
    website_blog: 'blog_draft',
    website: 'blog_draft',
    daily: 'daily_report',
    report: 'daily_report',
    email: 'parent_email',
    philosophy: 'teaching_philosophy_note',
    teaching_note: 'teaching_philosophy_note',
    clip: 'short_clip',
  };
  return aliases[value] || value;
}

function contentSummaryForPrompt(job, { publicOnly = false } = {}) {
  const parsed = typeof job.parse_json === 'string' ? safeJsonParse(job.parse_json) : (job.parse_json || {});
  const classContent = classContentFieldsFromParsed(parsed);
  const publicText = (value, maxChars = 1200) => publicOnly
    ? sanitizePublicLearningText(value, maxChars)
    : value;
  const publicList = (values, limit = 20) => {
    const list = Array.isArray(values) ? values : toJsonArray(values);
    const filtered = publicOnly
      ? list.map((item) => sanitizePublicLearningText(classContentItemText(item), 800)).filter(Boolean)
      : list;
    return filtered.slice(0, limit);
  };
  return JSON.stringify({
    source_id: job.id || null,
    title: publicText(job.title, 240),
    caption: publicText(job.caption, 800),
    summary: publicText(classContent.summary || '', 1600),
    topics: publicList(classContent.topics),
    discussions: publicList(classContent.discussions),
    sources: publicList(classContent.sources),
    student_questions: publicList(classContent.studentQuestions),
    highlights: publicList(classContent.highlights),
  }, null, 2);
}

function safeJsonParse(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

function sanitizeFileName(value) {
  return String(value || '')
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 120) || 'file';
}

function ensureDirectory(dirPath) {
  fs.mkdirSync(dirPath, { recursive: true });
  return dirPath;
}

function formatBytes(bytes) {
  const size = Number(bytes || 0);
  if (size >= 1024 * 1024 * 1024) return `${(size / 1024 / 1024 / 1024).toFixed(1)}GB`;
  if (size >= 1024 * 1024) return `${Math.ceil(size / 1024 / 1024)}MB`;
  if (size >= 1024) return `${Math.ceil(size / 1024)}KB`;
  return `${size}B`;
}

function mimeTypeFromFilename(filename, fallback = '') {
  const explicit = String(fallback || '').trim().toLowerCase();
  if (/^(audio|video)\//i.test(explicit)) return explicit;
  const ext = path.extname(String(filename || '')).toLowerCase();
  const byExt = {
    '.aac': 'audio/aac',
    '.aif': 'audio/aiff',
    '.aiff': 'audio/aiff',
    '.flac': 'audio/flac',
    '.m4a': 'audio/mp4',
    '.mp3': 'audio/mpeg',
    '.oga': 'audio/ogg',
    '.ogg': 'audio/ogg',
    '.opus': 'audio/ogg',
    '.wav': 'audio/wav',
    '.webm': 'video/webm',
    '.m4v': 'video/mp4',
    '.mov': 'video/quicktime',
    '.mp4': 'video/mp4',
    '.mpeg': 'video/mpeg',
    '.mpg': 'video/mpeg',
  };
  return byExt[ext] || explicit || 'application/octet-stream';
}

function isAudioVideoMime(mimeType) {
  return /^audio\//i.test(String(mimeType || '')) || /^video\//i.test(String(mimeType || ''));
}

function readRequestBuffer(req, { maxBytes = PARENT_MEETING_UPLOAD_MAX_BYTES } = {}) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let total = 0;
    let settled = false;
    req.on('data', (chunk) => {
      if (settled) return;
      total += chunk.length;
      if (total > maxBytes) {
        settled = true;
        const error = new Error(`Upload is too large. Maximum size is ${formatBytes(maxBytes)}.`);
        error.statusCode = 413;
        req.destroy(error);
        reject(error);
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (settled) return;
      settled = true;
      resolve(Buffer.concat(chunks));
    });
    req.on('error', (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    });
  });
}

function parseMultipartContentDisposition(value = '') {
  const result = {};
  const parts = String(value || '').split(';').map((part) => part.trim()).filter(Boolean);
  result.type = parts.shift() || '';
  for (const part of parts) {
    const eqIndex = part.indexOf('=');
    if (eqIndex < 0) continue;
    const key = part.slice(0, eqIndex).trim().toLowerCase();
    let item = part.slice(eqIndex + 1).trim();
    if (item.startsWith('"') && item.endsWith('"')) {
      item = item.slice(1, -1).replace(/\\"/g, '"');
    }
    result[key] = item;
  }
  return result;
}

function parseMultipartFormBuffer(buffer, boundary) {
  const delimiter = Buffer.from(`--${boundary}`);
  const headerDivider = Buffer.from('\r\n\r\n');
  const fields = {};
  const files = [];
  let cursor = buffer.indexOf(delimiter);
  while (cursor >= 0) {
    cursor += delimiter.length;
    if (buffer[cursor] === 45 && buffer[cursor + 1] === 45) break;
    if (buffer[cursor] === 13 && buffer[cursor + 1] === 10) cursor += 2;

    const headerEnd = buffer.indexOf(headerDivider, cursor);
    if (headerEnd < 0) break;
    const headersText = buffer.slice(cursor, headerEnd).toString('utf8');
    const headers = {};
    for (const line of headersText.split(/\r\n/)) {
      const colon = line.indexOf(':');
      if (colon < 0) continue;
      headers[line.slice(0, colon).trim().toLowerCase()] = line.slice(colon + 1).trim();
    }

    const dataStart = headerEnd + headerDivider.length;
    const next = buffer.indexOf(delimiter, dataStart);
    if (next < 0) break;
    let dataEnd = next;
    if (buffer[dataEnd - 2] === 13 && buffer[dataEnd - 1] === 10) dataEnd -= 2;
    const data = buffer.slice(dataStart, dataEnd);
    const disposition = parseMultipartContentDisposition(headers['content-disposition']);
    const name = disposition.name || '';
    const filename = disposition.filename || disposition['filename*'] || '';
    if (name && filename) {
      files.push({
        name,
        filename,
        mimeType: mimeTypeFromFilename(filename, headers['content-type']),
        data,
        size: data.length,
      });
    } else if (name) {
      fields[name] = data.toString('utf8');
    }
    cursor = next;
  }
  return { fields, files };
}

async function parseMultipartFormRequest(req, { maxBytes = PARENT_MEETING_UPLOAD_MAX_BYTES } = {}) {
  const contentType = String(req.headers['content-type'] || '');
  const match = contentType.match(/boundary=(?:"([^"]+)"|([^;]+))/i);
  if (!match) {
    const error = new Error('Expected a multipart form upload.');
    error.statusCode = 400;
    throw error;
  }
  const raw = await readRequestBuffer(req, { maxBytes });
  return parseMultipartFormBuffer(raw, match[1] || match[2]);
}

function getTranscriptText(transcription) {
  if (!transcription) return '';
  if (typeof transcription === 'string') return transcription;
  if (typeof transcription.text === 'string') return transcription.text;
  if (Array.isArray(transcription.chunks)) {
    return transcription.chunks
      .map((chunk, index) => {
        const text = getTranscriptText(chunk.transcription);
        return text ? `[part ${index + 1}]\n${text}` : '';
      })
      .filter(Boolean)
      .join('\n\n')
      .trim();
  }
  if (Array.isArray(transcription.segments)) {
    return transcription.segments
      .map((segment) => {
        const speaker = segment.speaker || segment.speaker_label || segment.label || '';
        const text = segment.text || '';
        return speaker ? `${speaker}: ${text}` : text;
      })
      .join('\n')
      .trim();
  }
  return '';
}

function runLocalProcess(command, args, options = {}) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, {
      cwd: __dirname,
      windowsHide: true,
      stdio: ['ignore', 'pipe', 'pipe'],
      ...options,
    });
    let stdout = '';
    let stderr = '';
    child.stdout?.on('data', (chunk) => { stdout += chunk.toString(); });
    child.stderr?.on('data', (chunk) => { stderr += chunk.toString(); });
    child.on('error', reject);
    child.on('close', (code) => {
      if (code === 0) resolve({ stdout, stderr });
      else reject(new Error(`${path.basename(command)} exited ${code}: ${(stderr || stdout).slice(0, 1000)}`));
    });
  });
}

async function createTranscriptionAudioChunks(localPath, descriptor) {
  if (!ffmpegPath) {
    throw new Error('ffmpeg is not available, so large media cannot be compressed or split automatically.');
  }

  const chunksDir = ensureDirectory(path.join(
    PARENT_MEETING_UPLOAD_DIR,
    getTodayDateInTimeZone(),
    'transcription-chunks',
    sanitizeFileName(path.basename(localPath, path.extname(localPath)))
  ));
  const outputPattern = path.join(chunksDir, 'part-%03d.mp3');
  await runLocalProcess(ffmpegPath, [
    '-hide_banner',
    '-y',
    '-i',
    localPath,
    '-vn',
    '-ac',
    '1',
    '-ar',
    '16000',
    '-b:a',
    '32k',
    '-f',
    'segment',
    '-segment_time',
    '600',
    '-reset_timestamps',
    '1',
    outputPattern,
  ]);

  const chunks = fs.readdirSync(chunksDir)
    .filter((name) => name.toLowerCase().endsWith('.mp3'))
    .sort()
    .map((name) => {
      const chunkPath = path.join(chunksDir, name);
      return {
        localPath: chunkPath,
        descriptor: { filename: name, mimeType: 'audio/mpeg' },
        size: fs.statSync(chunkPath).size,
      };
    })
    .filter((chunk) => chunk.size > 0);
  if (!chunks.length) throw new Error('ffmpeg did not create transcription chunks.');
  const tooLarge = chunks.find((chunk) => chunk.size > TRANSCRIPTION_MAX_BYTES);
  if (tooLarge) throw new Error(`A compressed audio chunk is still ${formatBytes(tooLarge.size)}.`);
  return {
    chunks,
    mode: 'ffmpeg-audio-chunks',
    chunksDir,
    originalMimeType: descriptor.mimeType,
  };
}

async function prepareTranscriptionInputs(localPath, descriptor) {
  const stats = fs.statSync(localPath);
  const isVideo = /^video\//i.test(String(descriptor.mimeType || ''));
  const shouldExtractAudio = isVideo || (stats.size > TRANSCRIPTION_MAX_BYTES && isAudioVideoMime(descriptor.mimeType));
  if (!shouldExtractAudio && stats.size <= TRANSCRIPTION_MAX_BYTES) {
    return {
      chunks: [{ localPath, descriptor, size: stats.size }],
      mode: 'original-file',
    };
  }
  if (!isAudioVideoMime(descriptor.mimeType)) {
    throw new Error(`File is ${formatBytes(stats.size)} and is not marked as audio/video.`);
  }
  return createTranscriptionAudioChunks(localPath, descriptor);
}

async function transcribeSingleMediaWithOpenAI(localPath, descriptor) {
  if (!OPENAI_API_KEY) {
    throw new Error('OPENAI_API_KEY is not configured for transcription.');
  }
  const stats = fs.statSync(localPath);
  if (stats.size > TRANSCRIPTION_MAX_BYTES) {
    throw new Error(`File is ${formatBytes(stats.size)}. OpenAI transcription upload limit is ${formatBytes(TRANSCRIPTION_MAX_BYTES)}.`);
  }
  const form = new FormData();
  form.append('model', OPENAI_TRANSCRIPTION_MODEL);
  form.append('file', new Blob([fs.readFileSync(localPath)], { type: descriptor.mimeType }), descriptor.filename);
  form.append('response_format', 'json');
  form.append(
    'prompt',
    'This is a Bnei Neviim Academy parent meeting recording. The audio may mix English and Hebrew. Preserve student names, parent concerns, goals, accountability decisions, attendance, follow-ups, and next check-in dates.'
  );

  const response = await fetch(`${OPENAI_BASE_URL.replace(/\/+$/, '')}/audio/transcriptions`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${OPENAI_API_KEY}` },
    body: form,
    signal: AbortSignal.timeout(OPENAI_REQUEST_TIMEOUT_MS),
  });
  const body = await response.text();
  if (!response.ok) {
    throw new Error(`OpenAI transcription ${response.status}: ${body.slice(0, 500)}`);
  }
  return JSON.parse(body);
}

async function transcribeMediaWithOpenAI(localPath, descriptor) {
  const prepared = await prepareTranscriptionInputs(localPath, descriptor);
  const chunks = [];
  for (let index = 0; index < prepared.chunks.length; index += 1) {
    const chunk = prepared.chunks[index];
    const transcription = await transcribeSingleMediaWithOpenAI(chunk.localPath, chunk.descriptor);
    chunks.push({
      index: index + 1,
      local_path: path.relative(__dirname, chunk.localPath).replace(/\\/g, '/'),
      size_bytes: chunk.size,
      transcription,
    });
  }
  const text = chunks
    .map((chunk) => {
      const text = getTranscriptText(chunk.transcription);
      return chunks.length > 1 ? `[part ${chunk.index}]\n${text}` : text;
    })
    .filter(Boolean)
    .join('\n\n')
    .trim();
  return {
    text,
    chunks,
    processing: {
      mode: prepared.mode,
      chunk_count: chunks.length,
      chunks_dir: prepared.chunksDir ? path.relative(__dirname, prepared.chunksDir).replace(/\\/g, '/') : null,
    },
  };
}

function ensureParentDirectory(filePath) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
}

function readJsonFile(filePath, fallback) {
  try {
    if (!fs.existsSync(filePath)) return fallback;
    const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    return parsed && typeof parsed === 'object' ? parsed : fallback;
  } catch {
    return fallback;
  }
}

function writeJsonFile(filePath, value) {
  ensureParentDirectory(filePath);
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`);
}

