let workspacePlatformDefaultsReady = false;
let workspacePlatformDefaultsPromise = null;
let serviceProviderDirectoryDefaultsReady = false;
let serviceProviderDirectoryDefaultsPromise = null;

async function ensureWorkspacePlatformDefaultsOnce(db = pool) {
  if (db !== pool) return ensureWorkspacePlatformDefaults(db);
  if (workspacePlatformDefaultsReady) return;
  if (!workspacePlatformDefaultsPromise) {
    workspacePlatformDefaultsPromise = ensureWorkspacePlatformDefaults(db)
      .then(() => {
        workspacePlatformDefaultsReady = true;
      })
      .finally(() => {
        workspacePlatformDefaultsPromise = null;
      });
  }
  return workspacePlatformDefaultsPromise;
}

async function ensureDefaultServiceProviderDirectoryOnce(db = pool) {
  if (db !== pool) return ensureDefaultServiceProviderDirectory(db);
  if (serviceProviderDirectoryDefaultsReady) return;
  if (!serviceProviderDirectoryDefaultsPromise) {
    serviceProviderDirectoryDefaultsPromise = ensureDefaultServiceProviderDirectory(db)
      .then(() => {
        serviceProviderDirectoryDefaultsReady = true;
      })
      .finally(() => {
        serviceProviderDirectoryDefaultsPromise = null;
      });
  }
  return serviceProviderDirectoryDefaultsPromise;
}

