async function getStudentParentNotificationRecord(studentId, db = pool) {
  const result = await db.query(
    `SELECT s.id,
            s.name,
            COALESCE(NULLIF(s.parent_name, ''), su.parent_name) AS parent_name,
            COALESCE(NULLIF(s.parent_email, ''), su.parent_email) AS parent_email,
            COALESCE(NULLIF(s.parent_phone, ''), su.parent_phone) AS parent_phone,
            s.signup_id
     FROM bna_students s
     LEFT JOIN signups su ON su.id = s.signup_id
     WHERE s.id = $1
       AND COALESCE(s.status, 'active') NOT IN ('inactive', 'archived')
     LIMIT 1`,
    [studentId]
  );
  return result.rows[0] || null;
}

async function hydrateStudentParentNotificationRecord(student, db = pool) {
  const row = await getStudentParentNotificationRecord(student?.id, db);
  return {
    ...(student || {}),
    ...(row || {}),
    id: student?.id || row?.id,
    name: student?.name || row?.name || '',
  };
}

function parentNotificationActionStatus(metadata = {}) {
  const action = metadata.parent_action && typeof metadata.parent_action === 'object' ? metadata.parent_action : {};
  const value = String(action.status || metadata.action_status || metadata.parent_action_status || 'pending').trim().toLowerCase();
  return ['approved', 'denied', 'pending'].includes(value) ? value : 'pending';
}

