async function getAssignmentWithStudents(id, db = pool) {
  const result = await db.query(
    `SELECT a.*,
      COALESCE(
        (
          SELECT json_agg(
            json_build_object(
              'id', vpj.id,
              'assignment_id', vpj.assignment_id,
              'source_url', vpj.source_url,
              'provider', vpj.provider,
              'status', vpj.status,
              'output_file_path', vpj.output_file_path,
              'output_file_url', vpj.output_file_url,
              'error_message', vpj.error_message,
              'metadata_json', vpj.metadata_json,
              'created_at', vpj.created_at,
              'updated_at', vpj.updated_at
            )
            ORDER BY vpj.created_at DESC, vpj.id DESC
          )
          FROM bna_video_processing_jobs vpj
          WHERE vpj.assignment_id = a.id
        ),
        '[]'
      ) AS video_processing_jobs,
      COALESCE(
        json_agg(
          json_build_object(
            'id', ast.id,
            'assignment_id', ast.assignment_id,
            'student_id', ast.student_id,
            'student_name', ast.student_name,
            'prompt_patch_text', ast.prompt_patch_text,
            'prompt_patch_instruction', ast.prompt_patch_instruction,
            'worksheet_body', ast.worksheet_body,
            'final_resolved_prompt', ast.final_resolved_prompt,
            'generated_worksheet', ast.generated_worksheet,
            'edited_worksheet', ast.edited_worksheet,
            'status', ast.status,
            'scheduled_start_at', ast.scheduled_start_at,
            'due_at', ast.due_at,
            'classroom_course_id', ast.classroom_course_id,
            'classroom_student_id', ast.classroom_student_id,
            'classroom_coursework_id', ast.classroom_coursework_id,
            'classroom_alternate_link', ast.classroom_alternate_link,
            'classroom_state', ast.classroom_state,
            'calendar_id', ast.calendar_id,
            'calendar_event_id', ast.calendar_event_id,
            'calendar_html_link', ast.calendar_html_link,
            'sync_status', ast.sync_status,
            'sync_error', ast.sync_error,
            'sync_payload_json', ast.sync_payload_json,
            'schedule_items', COALESCE(
              (
                SELECT json_agg(
                  json_build_object(
                    'id', si.id,
                    'assignment_id', si.assignment_id,
                    'assignment_student_id', si.assignment_student_id,
                    'student_id', si.student_id,
                    'title', si.title,
                    'start_at', si.start_at,
                    'end_at', si.end_at,
                    'timezone', si.timezone,
                    'source', si.source,
                    'google_calendar_event_id', si.google_calendar_event_id,
                    'google_classroom_coursework_id', si.google_classroom_coursework_id,
                    'recurrence_json', si.recurrence_json,
                    'chunk_index', si.chunk_index,
                    'total_chunks', si.total_chunks,
                    'display_label', si.display_label,
                    'metadata', si.metadata
                  )
                  ORDER BY si.start_at ASC NULLS LAST, si.id ASC
                )
                FROM bna_schedule_items si
                WHERE si.assignment_student_id = ast.id
              ),
              '[]'
            ),
            'metadata', ast.metadata,
            'created_at', ast.created_at,
            'updated_at', ast.updated_at
          )
          ORDER BY ast.student_name ASC NULLS LAST, ast.id ASC
        ) FILTER (WHERE ast.id IS NOT NULL),
        '[]'
      ) AS students
     FROM bna_assignments a
     LEFT JOIN bna_assignment_students ast ON ast.assignment_id = a.id
     WHERE a.id = $1
     GROUP BY a.id
     LIMIT 1`,
    [id]
  );
  return result.rows[0] ? assignmentView(result.rows[0]) : null;
}

async function getAssignmentsForStudentPortal(studentId, { audience = 'student' } = {}, db = pool) {
  const result = await db.query(
    `SELECT a.id AS assignment_id,
            a.title,
            a.instructions,
            a.youtube_url,
            a.youtube_video_id,
            a.youtube_metadata_json,
            a.material_url,
            a.language_mode,
            a.worksheet_type,
            a.schedule_text,
            a.schedule_plan,
            a.sync_mode,
            a.status AS assignment_status,
            ast.id AS assignment_student_id,
            ast.student_id,
            ast.student_name,
            ast.worksheet_body,
            ast.generated_worksheet,
            ast.edited_worksheet,
            ast.status,
            ast.scheduled_start_at,
            ast.due_at,
            ast.classroom_coursework_id,
            ast.classroom_alternate_link,
            ast.classroom_state,
            ast.calendar_event_id,
            ast.calendar_html_link,
            ast.sync_status,
            COALESCE(
              (
                SELECT json_agg(
                  json_build_object(
                    'id', si.id,
                    'start_at', si.start_at,
                    'end_at', si.end_at,
                    'timezone', si.timezone,
                    'source', si.source,
                    'chunk_index', si.chunk_index,
                    'total_chunks', si.total_chunks,
                    'display_label', si.display_label,
                    'metadata', si.metadata
                  )
                  ORDER BY si.start_at ASC NULLS LAST, si.id ASC
                )
                FROM bna_schedule_items si
                WHERE si.assignment_student_id = ast.id
              ),
              '[]'
            ) AS schedule_items,
            ast.metadata,
            ast.updated_at,
            ast.created_at
     FROM bna_assignment_students ast
     JOIN bna_assignments a ON a.id = ast.assignment_id
     WHERE ast.student_id = $1
       AND COALESCE(a.status, 'draft') <> 'archived'
       AND COALESCE(ast.status, 'assigned') <> 'archived'
     ORDER BY COALESCE(ast.scheduled_start_at, ast.due_at, ast.created_at) ASC, ast.id DESC
     LIMIT 50`,
    [studentId]
  );
  return result.rows
    .filter((row) => {
      const metadata = parseJsonMaybe(row.metadata);
      const visible = audience === 'parent'
        ? metadata.parent_visible ?? metadata.share_with_parent
        : metadata.student_visible ?? metadata.share_with_student;
      return visibilityFlag(visible, true);
    })
    .map((row) => {
      const scheduleAt = row.scheduled_start_at || row.due_at || row.created_at;
      const scheduleDate = scheduleAt ? toIsoDateValue(scheduleAt) : '';
      const today = getTodayDateInTimeZone();
      const status = String(row.status || '').toLowerCase();
      const bucket = ['done', 'submitted'].includes(status)
        ? 'completed'
        : scheduleDate === today
          ? 'today'
          : scheduleDate && scheduleDate > today
            ? 'upcoming'
            : 'assignments';
      return {
        id: row.assignment_student_id,
        assignment_id: row.assignment_id,
        student_id: row.student_id,
        student_name: row.student_name,
        title: row.title,
        instructions: row.instructions || '',
        youtube_url: row.youtube_url || '',
        youtube_video_id: row.youtube_video_id || '',
        youtube_metadata_json: parseJsonMaybe(row.youtube_metadata_json),
        material_url: row.material_url || '',
        language_mode: row.language_mode,
        worksheet_type: row.worksheet_type,
        schedule_text: row.schedule_text || '',
        schedule_plan: parseJsonMaybe(row.schedule_plan),
        schedule_items: Array.isArray(row.schedule_items) ? row.schedule_items : [],
        schedule_bucket: bucket,
        google_classroom_status: row.classroom_coursework_id
          ? (row.classroom_state || 'synced')
          : row.sync_status || 'not_synced',
        google_calendar_status: row.calendar_event_id
          ? 'synced'
          : row.sync_status || 'not_synced',
        sync_mode: row.sync_mode,
        assignment_status: row.assignment_status,
        status: row.status,
        scheduled_start_at: row.scheduled_start_at,
        due_at: row.due_at,
        worksheet_body: row.edited_worksheet || row.worksheet_body || row.generated_worksheet || '',
        generated_worksheet: row.generated_worksheet || '',
        edited_worksheet: row.edited_worksheet || '',
        classroom_coursework_id: row.classroom_coursework_id || '',
        classroom_alternate_link: row.classroom_alternate_link || '',
        classroom_state: row.classroom_state || '',
        calendar_event_id: row.calendar_event_id || '',
        calendar_html_link: row.calendar_html_link || '',
        sync_status: row.sync_status || '',
        metadata: parseJsonMaybe(row.metadata),
        updated_at: row.updated_at,
        created_at: row.created_at,
      };
    });
}

async function getCalendarEventsForStudentPortal(studentId, { audience = 'student' } = {}, db = pool) {
  const visibilityList = audience === 'parent'
    ? ['parent', 'student', 'public']
    : ['student', 'public'];
  const result = await db.query(
    `SELECT *
     FROM bna_calendar_events
     WHERE workspace_key = 'bna'
       AND status NOT IN ('cancelled', 'archived')
       AND visibility = ANY($2::text[])
       AND start_at >= (CURRENT_DATE - INTERVAL '30 days')
       AND start_at <= (CURRENT_DATE + INTERVAL '180 days')
       AND (
         visibility = 'public'
         OR COALESCE(related_type, '') = ''
         OR related_type IN ('class_session', 'provider_program')
         OR (related_type = 'student' AND related_id = $1)
         OR (
           related_type = 'assignment'
           AND related_id IN (
             SELECT assignment_id
             FROM bna_assignment_students
             WHERE student_id = $1
               AND COALESCE(status, 'assigned') <> 'archived'
           )
         )
         OR COALESCE(metadata_json->>'student_id', metadata_json->>'studentId', '') = $1::text
         OR COALESCE(metadata_json->'student_ids', '[]'::jsonb) ? $1::text
         OR COALESCE(metadata_json->'studentIds', '[]'::jsonb) ? $1::text
       )
     ORDER BY start_at ASC, id ASC
     LIMIT 100`,
    [studentId, visibilityList]
  );
  return result.rows.map(calendarEventView).filter(Boolean);
}

async function findOrCreateGHLContact(email, firstName, lastName, phone, customFields = {}) {
  // Search for existing contact
  const searchRes = await ghlRequest(`/contacts?locationId=${GHL_LOCATION_ID}&query=${encodeURIComponent(email)}`);

  let contactId;
  if (searchRes.contacts && searchRes.contacts.length > 0) {
    contactId = searchRes.contacts[0].id;
    // Update existing
    await ghlRequest(`/contacts/${contactId}`, {
      method: 'PUT',
      body: JSON.stringify({
        firstName,
        lastName,
        email,
        phone,
        ...customFields
      })
    });
  } else {
    // Create new
    const createRes = await ghlRequest('/contacts', {
      method: 'POST',
      body: JSON.stringify({
        locationId: GHL_LOCATION_ID,
        firstName,
        lastName,
        email,
        phone,
        ...customFields
      })
    });
    contactId = createRes.contact.id;
  }

  return contactId;
}

function syntheticGhlStudentEmail({ signupId, studentName, parentEmail, parentPhone } = {}) {
  const rawKey = signupId
    ? `signup-${signupId}`
    : `${studentName || 'student'}-${parentEmail || parentPhone || 'no-parent-contact'}`;
  const slug = String(rawKey)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 72) || 'unknown-student';
  return `bna-student-${slug}@bna-student.invalid`;
}

async function addTagToContact(contactId, tag) {
  await ghlRequest(`/contacts/${contactId}/tags`, {
    method: 'POST',
    body: JSON.stringify({ tags: [tag] })
  });
}

