app.get('/api/google/oauth/start', (req, res) => {
  try {
    const redirectUri = req.query.redirect_uri || GOOGLE_REDIRECT_URI;
    const oauth2Client = createGoogleOAuthClient(redirectUri);
    const connectionRole = googleAuthService.normalizeGoogleConnectionRole(
      req.query.role || req.query.connection_role || req.query.account_type || 'admin_teacher'
    );
    const featureList = googleAuthService.parseGoogleScopeList(req.query.features || req.query.feature);
    const requestedScopes = googleAuthService.parseGoogleScopeList(req.query.scopes || req.query.scope);
    const hasExplicitScopeRequest = Boolean(
      req.query.role || req.query.connection_role || req.query.account_type ||
      req.query.features || req.query.feature || req.query.scopes || req.query.scope
    );
    const scopes = googleAuthService.googleScopesForConnection({
      role: connectionRole,
      features: featureList,
      requestedScopes,
      configuredScopes: GOOGLE_SCOPES,
      includeConfiguredScopes: !hasExplicitScopeRequest,
    });
    const setupDrivePipeline = !hasExplicitScopeRequest
      || featureList.map((feature) => String(feature).toLowerCase().replace(/[-\s]+/g, '_')).includes('drive_pipeline')
      || ['drive', 'drive_pipeline', 'true', '1'].includes(String(req.query.setup || '').toLowerCase());
    const url = oauth2Client.generateAuthUrl({
      access_type: 'offline',
      prompt: 'consent',
      scope: scopes,
      include_granted_scopes: true,
      state: Buffer.from(JSON.stringify({
        setup: true,
        setupDrivePipeline,
        connectionRole,
        features: featureList,
        scopes,
        studentId: req.query.student_id || null,
        parentEmail: req.query.parent_email || null,
        redirectUri,
        ts: Date.now(),
      })).toString('base64url'),
    });
    res.redirect(url);
  } catch (err) {
    res.status(500).send(`Google OAuth start failed: ${err.message}`);
  }
});

app.get('/api/google/oauth/callback', async (req, res) => {
  const { code, error, state } = req.query;
  if (error) {
    return res.status(400).send(`Google OAuth error: ${error}`);
  }
  if (!code) {
    return res.status(400).send('Google OAuth callback missing code');
  }

  try {
    let parsedState = {};
    try {
      parsedState = JSON.parse(Buffer.from(String(state || ''), 'base64url').toString('utf8'));
    } catch {}

    const redirectUri = parsedState.redirectUri || GOOGLE_REDIRECT_URI;
    const oauth2Client = createGoogleOAuthClient(redirectUri);
    const { tokens } = await oauth2Client.getToken(String(code));
    oauth2Client.setCredentials(tokens);
    const connectionRole = googleAuthService.normalizeGoogleConnectionRole(parsedState.connectionRole);
    const grantedScopes = googleAuthService.parseGoogleScopeList(parsedState.scopes?.length ? parsedState.scopes : GOOGLE_SCOPES);
    const connection = await saveGoogleConnection({
      role: connectionRole,
      tokens,
      scopes: grantedScopes,
      studentId: parsedState.studentId || null,
      parentEmail: parsedState.parentEmail || '',
      metadata: {
        source: 'google_oauth_callback',
        features: parsedState.features || [],
        setup_drive_pipeline: Boolean(parsedState.setupDrivePipeline),
      },
    });
    let pipeline = null;
    let folderConfig = null;
    if (parsedState.setupDrivePipeline) {
      pipeline = await ensureBnaDrivePipeline(oauth2Client);
      folderConfig = {
        root: pipeline.root.id,
        websiteMomentsIntake: pipeline.websiteMomentsIntake.id,
        stages: Object.fromEntries(Object.entries(pipeline.folders).map(([name, folder]) => [name, folder.id])),
        sourceOfTruth: {
          transcripts: 'GitHub content-memory/transcripts plus live app database',
          brandKit: 'GitHub brand-kit/',
          platformMemory: 'GitHub content-memory/',
          driveRole: 'operator upload/source-media library only',
          updatedAt: new Date().toISOString(),
        },
        simplifiedFolders: {
          rawIntake: pipeline.folders['01 Raw Intake'].id,
          websiteImages: pipeline.websiteMomentsIntake.id,
          processing: pipeline.folders['02 Ingesting'].id,
          processedRecordings: pipeline.folders['04 Parsed'].id,
          approvedAssets: pipeline.folders['10 Approved'].id,
          failedNeedsReview: pipeline.folders['99 Failed'].id,
          legacyArchive: pipeline.legacy?.id || null,
        },
        brandKit: pipeline.brandKit.id,
        brandDocs: Object.fromEntries(Object.entries(pipeline.brandDocs).map(([name, file]) => [name, file.id])),
        platformMemory: pipeline.platformMemory.id,
        platformDocs: Object.fromEntries(Object.entries(pipeline.platformDocs).map(([name, file]) => [name, file.id])),
      };
    }
    const secretsDir = path.join(__dirname, '.secrets');
    fs.mkdirSync(secretsDir, { recursive: true });
    const envLines = [
      `GOOGLE_CLIENT_ID=${loadGoogleOAuthClient().clientId}`,
      'GOOGLE_CLIENT_SECRET=<paste from your OAuth client JSON>',
      `GOOGLE_REDIRECT_URI=${redirectUri}`,
      tokens.refresh_token ? `GOOGLE_REFRESH_TOKEN=${tokens.refresh_token}` : 'GOOGLE_REFRESH_TOKEN=<no refresh token returned; re-run from /api/google/oauth/start>',
      `GOOGLE_SCOPES=${grantedScopes.join(' ')}`,
    ];
    if (folderConfig) {
      envLines.push(
        `GOOGLE_DRIVE_PIPELINE_ROOT_NAME=${GOOGLE_DRIVE_PIPELINE_ROOT_NAME}`,
        `GOOGLE_DRIVE_PIPELINE_FOLDER_ID=${pipeline.root.id}`,
        `GOOGLE_DRIVE_PIPELINE_CONFIG=${JSON.stringify(folderConfig)}`
      );
    }
    if (tokens.refresh_token && connectionRole === 'admin_teacher') {
      fs.writeFileSync(path.join(secretsDir, 'google-refresh-token.txt'), `${tokens.refresh_token}\n`);
    } else if (tokens.refresh_token) {
      fs.writeFileSync(
        path.join(secretsDir, `google-refresh-token-${connectionRole}-${connection.id}.txt`),
        `${tokens.refresh_token}\n`
      );
    }
    if (folderConfig) {
      fs.writeFileSync(path.join(secretsDir, 'google-drive-pipeline.json'), `${JSON.stringify(folderConfig, null, 2)}\n`);
      fs.writeFileSync(path.join(secretsDir, 'railway-google-env.txt'), `${envLines.join('\n')}\n`);
    }

    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    const envHtml = folderConfig
      ? `<p class="warn">These values include secrets. Paste them into Railway variables, then close this page.</p><pre>${envLines.join('\n').replace(/</g, '&lt;')}</pre>`
      : '<p>This connection was saved in the BNA Google connections table. No Drive pipeline setup was requested.</p>';
    const driveHtml = pipeline
      ? `<p>The Drive pipeline folders were created or confirmed under <strong>${GOOGLE_DRIVE_PIPELINE_ROOT_NAME}</strong>.</p><p>Root folder: <a href="${pipeline.root.webViewLink}" target="_blank" rel="noreferrer">${pipeline.root.webViewLink}</a></p>`
      : '';
    res.send(`<!doctype html>
<html><head><title>BNA Google Connected</title><style>
body{font-family:system-ui,sans-serif;max-width:920px;margin:40px auto;padding:0 20px;line-height:1.5}
pre{white-space:pre-wrap;background:#0f172a;color:#e2e8f0;padding:18px;border-radius:12px}
.ok{color:#166534;font-weight:700}.warn{color:#9a3412}
</style></head><body>
<h1 class="ok">Google connected for BNA V2</h1>
<p>Connection role: <strong>${connectionRole.replace(/_/g, '/')}</strong>${connection.account_email ? ` for <strong>${connection.account_email}</strong>` : ''}.</p>
${driveHtml}
${envHtml}
</body></html>`);
  } catch (err) {
    res.status(500).send(`Google OAuth callback failed: ${err.message}`);
  }
});

