async function createProviderOnboardingFollowups(context = {}) {
  const providerId = Number(context.provider_id || context.providerId);
  if (!Number.isFinite(providerId) || providerId <= 0) return null;

  const providerName = limitText(context.provider_name || context.providerName, 160) || `Provider #${providerId}`;
  const contactName = limitText(context.contact_name || context.contactName, 160) || 'Provider contact';
  const contactEmail = normalizeEmail(context.contact_email || context.contactEmail);
  const contactPhone = limitText(context.contact_phone || context.contactPhone, 80);
  const interest = limitText(context.interest || 'free_listing', 120) || 'free_listing';
  const commercialModel = safeCommercialModel(context.commercial_model || context.commercialModel);
  const entitlementPlan = safeProviderPlan(context.entitlement_plan || context.entitlementPlan, commercialModel);
  const projectId = Number(context.project_id || context.projectId) || null;

  const pipelineResult = await pool.query(
    `INSERT INTO bna_pipeline_cards (
       workspace_key, pipeline_key, stage_key, title, summary, contact_type, contact_id,
       owner_name, status, source, next_action, metadata_json
     ) VALUES (
       'platform', 'provider_onboarding', 'inbox', $1, $2, 'service_provider', $3,
       'Shloimie', 'active', 'lead', 'Review provider commercial mode and approve or reject listing.', $4::jsonb
     )
     RETURNING *`,
    [
      `Provider onboarding: ${providerName}`,
      `${contactName} requested ${interest}. ${context.notes ? `Notes: ${limitText(context.notes, 240)}` : ''}`.trim(),
      providerId,
      JSON.stringify({ provider_id: providerId, commercial_model: commercialModel, entitlement_plan: entitlementPlan }),
    ]
  );

  const taskNotes = [
    `Provider: ${providerName}`,
    `Contact: ${contactName}${contactEmail ? ` <${contactEmail}>` : ''}${contactPhone ? ` / ${contactPhone}` : ''}`,
    `Interest: ${interest}`,
    `Commercial model: ${commercialModel}`,
    `Entitlement plan: ${entitlementPlan}`,
    'No listing, automation, payment, email, WhatsApp, or social action is live until BNA approves it.',
    context.notes ? `Notes: ${context.notes}` : '',
  ].filter(Boolean).join('\n');
  const taskSourceContext = {
    provider_id: providerId,
    pipeline_card_id: pipelineResult.rows[0]?.id,
    commercial_model: commercialModel,
    entitlement_plan: entitlementPlan,
  };
  const taskResult = await pool.query(
    `INSERT INTO bna_tasks (
       title, notes, stage, category, urgency, source, source_context,
       created_by, assigned_to, ai_parsed, project_id, decision_required, author
     )
     VALUES ($1, $2, 'assigned', 'operations', 'this_week', 'web', $3,
       'provider_onboarding', 'Shloimie', $4::jsonb, $5, FALSE, 'provider_onboarding')
     RETURNING *`,
    [
      `Review provider onboarding: ${providerName}`,
      taskNotes,
      sourceContextToText(taskSourceContext),
      JSON.stringify({
        parser: 'provider_onboarding-v1',
        kind: 'task',
        display_title: `Review provider onboarding: ${providerName}`,
        original_text: taskNotes,
        project: DEFAULT_PROJECT_KEY,
        decision_required: false,
      }),
      projectId,
    ]
  );

  await seedProviderCommercialRows(
    {
      id: providerId,
      commercial_model: commercialModel,
      entitlement_plan: entitlementPlan,
      source_of_truth: 'unknown_pending_access',
      integration_status: 'no_access',
    },
    { planKey: entitlementPlan, db: pool }
  );

  return {
    pipeline_card_id: pipelineResult.rows[0]?.id || null,
    review_task_id: taskResult.rows[0]?.id || null,
  };
}

app.post('/api/provider-onboarding', async (req, res) => {
  const body = req.body || {};
  const providerName = limitText(body.provider_name || body.providerName || body.name, 160);
  const contactName = limitText(body.contact_name || body.contactName, 160);
  const contactEmail = normalizeEmail(body.email || body.contact_email || body.contactEmail);
  const contactPhone = limitText(body.phone || body.whatsapp || body.contact_phone || body.contactPhone, 80);
  if (!providerName || !contactName || !contactEmail) {
    return res.status(400).json({ error: 'Provider name, contact name, and email are required' });
  }

  const interest = String(body.interested_in || body.interest || 'free_listing').trim().toLowerCase();
  const commercialModel = interest.includes('school')
    ? 'school_subscription'
    : /ai[_\s-]*max|paid|funnel|setup|managed|automation|lead|marketing|ads?/.test(interest)
      ? 'paid_setup'
      : 'free_listing';
  const entitlementPlan = safeProviderPlan('', commercialModel);
  const serviceTitle = limitText(body.program_description || body.program || body.service_description || body.description, 180);
  const serviceCategory = limitText(body.service_category || body.serviceCategory || body.category, 120);
  const serviceArea = limitText(body.service_area || body.serviceArea || body.location, 180);
  const agesServed = limitText(body.ages_served || body.agesServed || body.age_range || body.ageRange, 120);

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const project = await ensureDefaultProjects(client);
    const providerResult = await client.query(
      `INSERT INTO bna_service_providers (
         project_id, provider_name, contact_name, contact_email, contact_phone,
         status, provider_status, commercial_model, entitlement_plan,
         source_of_truth, integration_status, setup_package, managed_services,
         public_listing_enabled, public_signup_enabled, claim_listing_enabled,
         internal_owner, commercial_notes, public_notes, private_notes, metadata
       ) VALUES (
         $1, $2, $3, $4, $5,
         'draft', 'draft', $6, $7,
         'unknown_pending_access', 'no_access', $8, $9::jsonb,
         $10, $11, TRUE,
         'Shloimie', $12, $13, $14, $15::jsonb
       )
       RETURNING *`,
      [
        project.bna.id,
        providerName,
        contactName,
        contactEmail,
        contactPhone || null,
        commercialModel,
        entitlementPlan,
        commercialModel === 'school_subscription' ? 'School workspace discovery' : commercialModel === 'paid_setup' ? 'Managed growth/setup discovery' : 'Free listing review',
        JSON.stringify({ requested_interest: interest }),
        commercialModel === 'free_listing',
        commercialModel !== 'free_listing',
        `Public onboarding requested: ${interest}. No listing is live until BNA reviews and approves it.`,
        limitText(body.program_description || body.description, 1200) || null,
        limitText(body.notes, 1200) || null,
        JSON.stringify({
          source: 'provider_onboarding',
          category: serviceCategory || null,
          service_type: body.service_type || body.serviceType || null,
          location: serviceArea || null,
          online: body.online || null,
          language: body.language || null,
          age_range: agesServed || null,
          types_kids_served: limitText(body.types_kids_served || body.typesKidsServed, 800) || null,
          experience_background: limitText(body.experience_background || body.experienceBackground, 1200) || null,
          problems_solved: limitText(body.problems_solved || body.problemsSolved, 1200) || null,
          years_active: limitText(body.years_active || body.yearsActive, 80) || null,
          pricing_structure: limitText(body.pricing_structure || body.pricingStructure, 500) || null,
          typical_charge: limitText(body.typical_charge || body.typicalCharge, 240) || null,
          discounts_group_options: limitText(body.discounts_group_options || body.discountsGroupOptions, 1200) || null,
          running_ads: limitText(body.running_ads || body.runningAds, 80) || null,
          ai_max_interest: /ai[_\s-]*max/.test(interest),
          website: body.website || null,
          raw_interest: interest,
        }),
      ]
    );
    const provider = providerResult.rows[0];
    await updateProviderPublicProfileFields(provider.id, {
      ...body,
      display_name: body.display_name || body.displayName || providerName,
      short_description: body.short_description || body.shortDescription || body.program_description || body.description,
      full_description: body.full_description || body.fullDescription || body.program_description || body.description,
      can_receive_messages: true,
    }, client);

    if (serviceTitle) {
      await client.query(
        `INSERT INTO bna_provider_services (
           provider_id, title, service_type, description, status, city, tags, metadata
         ) VALUES ($1, $2, $3, $4, 'draft', $5, $6, $7::jsonb)`,
        [
          provider.id,
          serviceTitle,
          limitText(body.service_type || body.serviceType || serviceCategory || 'learning', 80) || 'learning',
          limitText(body.program_description || body.description, 1600) || null,
          limitText(serviceArea, 120) || null,
          normalizeTextArray([serviceCategory, body.language, agesServed].filter(Boolean)),
          JSON.stringify({ source: 'provider_onboarding', public_pending_review: true }),
        ]
      );
    }

    const followupContext = {
      project_id: project.bna.id,
      provider_id: provider.id,
      provider_name: providerName,
      contact_name: contactName,
      contact_email: contactEmail,
      contact_phone: contactPhone || null,
      interest,
      commercial_model: commercialModel,
      entitlement_plan: entitlementPlan,
      notes: limitText(body.notes, 1200) || '',
    };

    await client.query('COMMIT');
    const rawIntakeText = limitText(body.raw_intake || body.rawIntake || body.intake_text || body.intakeText, 12000) || '';
    let intakeResult = null;
    if (rawIntakeText) {
      intakeResult = await createProviderIntakeRecord({
        providerId: provider.id,
        rawText: rawIntakeText,
        source: 'provider_form',
        metadata: { source: 'provider_onboarding_form', provider_name: providerName },
      }).catch((error) => ({ error: error.message }));
      if (intakeResult?.parsed_fields) {
        await updateProviderPublicProfileFields(provider.id, intakeResult.parsed_fields).catch(() => {});
      }
    }
    const savedProvider = {
      ...provider,
      services: serviceTitle ? [{ title: serviceTitle, status: 'draft' }] : [],
      entitlements: providerEntitlementRowsForPlan(entitlementPlan),
      integrations: [],
      access_checklist: [],
    };
    res.json({
      success: true,
      provider: publicServiceProviderView(savedProvider),
      commercial_model: commercialModel,
      entitlement_plan: entitlementPlan,
      pipeline_card_id: null,
      review_task_id: null,
      followup_status: 'queued',
      intake: intakeResult ? {
        parsed_fields: intakeResult.parsed_fields || {},
        open_questions: intakeResult.open_questions || [],
        setup_tasks: intakeResult.setup_tasks || [],
        confidence: intakeResult.confidence || 0,
        error: intakeResult.error || '',
      } : null,
      message: 'Provider onboarding received. BNA will review before anything is published or automated.',
    });
    createProviderOnboardingFollowups(followupContext)
      .catch((followupError) => console.error('Provider onboarding follow-up error:', followupError));
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/provider-onboarding/intake', async (req, res) => {
  const body = req.body || {};
  const providerId = body.provider_id || body.providerId ? Number(body.provider_id || body.providerId) : null;
  const rawText = String(body.raw_text || body.rawText || body.text || '').trim();
  const fileUrl = String(body.file_url || body.fileUrl || '').trim();
  if (providerId && !Number.isFinite(providerId)) return res.status(400).json({ error: 'provider_id must be numeric' });
  try {
    if (providerId) {
      const provider = (await pool.query(
        `SELECT id
         FROM bna_service_providers
         WHERE id = $1
           AND status NOT IN ('rejected', 'archived')
         LIMIT 1`,
        [providerId]
      )).rows[0];
      if (!provider) return res.status(404).json({ error: 'Provider was not found' });
    }
    const intake = await createProviderIntakeRecord({
      providerId,
      sessionKey: body.session_key || body.sessionKey || '',
      rawText,
      fileUrl,
      source: body.source || 'natural_language',
      metadata: { source: 'provider_onboarding_intake_api' },
    });
    if (providerId && intake.parsed_fields) {
      await updateProviderPublicProfileFields(providerId, intake.parsed_fields).catch(() => {});
    }
    res.json({ success: true, ...intake });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

