app.post('/api/provider-portal/login', async (req, res) => {
  const username = limitText(req.body?.username || req.body?.login_username, 120);
  const password = String(req.body?.password || '');
  if (!username || !password) {
    clearProviderSessionCookie(res);
    return res.status(400).json({ success: false, error: 'Username and password are required' });
  }

  try {
    const provider = (await pool.query(
      `SELECT *
       FROM bna_service_providers
       WHERE lower(COALESCE(login_username, '')) = lower($1)
         AND password_hash IS NOT NULL
         AND status NOT IN ('draft', 'rejected', 'archived')
       LIMIT 1`,
      [username]
    )).rows[0] || null;

    if (!provider || !verifyParentPassword(password, provider.password_hash)) {
      clearProviderSessionCookie(res);
      return res.status(401).json({ success: false, error: 'Invalid provider credentials' });
    }

    const sessionId = await issueProviderSession(provider.id);
    await pool.query(`UPDATE bna_service_providers SET last_login_at = NOW(), updated_at = NOW() WHERE id = $1`, [provider.id]);
    setProviderSessionCookie(res, sessionId);
    const payload = await getProviderPortalPayload(provider.id);
    res.json({ success: true, sessionId, ...payload });
  } catch (err) {
    clearProviderSessionCookie(res);
    res.status(500).json({ success: false, error: err.message });
  }
});

app.post('/api/provider-portal/logout', async (req, res) => {
  const cookies = parseCookies(req);
  await clearProviderSession(cookies[PROVIDER_SESSION_COOKIE_NAME]);
  clearProviderSessionCookie(res);
  res.json({ success: true });
});

