app.post('/api/provider-portal/messages/:id/reply', requireProviderSession, async (req, res) => {
  const messageId = Number(req.params.id);
  const body = String(req.body?.body || req.body?.message || '').trim();
  if (!Number.isFinite(messageId)) return res.status(400).json({ error: 'A valid message id is required' });
  if (!body) return res.status(400).json({ error: 'Reply body is required' });
  if (body.length > 3000) return res.status(400).json({ error: 'Reply body is too long' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const original = (await client.query(
      `SELECT *
       FROM bna_provider_messages
       WHERE id = $1
         AND provider_id = $2
         AND status <> 'archived'
       LIMIT 1`,
      [messageId, req.providerSession.providerId]
    )).rows[0];
    if (!original) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Message was not found for this provider' });
    }
    const reply = (await client.query(
      `INSERT INTO bna_provider_messages (
         provider_id, service_id, parent_email, student_id, direction, channel,
         subject, body, status, source, source_context, metadata
       ) VALUES (
         $1, $2, $3, $4, 'provider_to_parent', 'portal',
         $5, $6, 'open', 'provider_portal', $7::jsonb, $8::jsonb
       )
       RETURNING *`,
      [
        original.provider_id,
        original.service_id || null,
        original.parent_email || null,
        original.student_id || null,
        original.subject || `Reply from ${req.providerSession.providerName || 'provider'}`,
        body,
        JSON.stringify({ source_message_id: original.id }),
        JSON.stringify({ provider_id: req.providerSession.providerId }),
      ]
    )).rows[0];
    await client.query(
      `UPDATE bna_provider_messages
       SET status = 'replied',
           updated_at = NOW()
       WHERE id = $1`,
      [original.id]
    );
    await client.query('COMMIT');
    const payload = await getProviderPortalPayload(req.providerSession.providerId);
    res.json({ success: true, reply, ...payload });
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    res.status(500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.patch('/api/provider-portal/profile', requireProviderSession, async (req, res) => {
  const allowed = new Set([
    'provider_name',
    'display_name',
    'category',
    'short_description',
    'full_description',
    'city',
    'neighborhood',
    'address',
    'service_area',
    'contact_name',
    'contact_email',
    'contact_phone',
    'whatsapp_phone',
    'website_url',
    'google_business_profile_url',
    'google_place_id',
    'profile_image_url',
    'public_notes',
  ]);
  const fields = [];
  const values = [];
  for (const [key, rawValue] of Object.entries(req.body || {})) {
    if (!allowed.has(key)) continue;
    const value = key === 'contact_email'
      ? normalizeEmail(rawValue)
      : limitText(rawValue, ['public_notes', 'full_description'].includes(key) ? 1600 : ['website_url', 'google_business_profile_url', 'profile_image_url'].includes(key) ? 520 : 220) || null;
    values.push(value);
    fields.push(`${key} = $${values.length}`);
  }
  if (!fields.length) return res.status(400).json({ error: 'No supported profile fields supplied' });
  values.push(req.providerSession.providerId);
  try {
    await pool.query(
      `UPDATE bna_service_providers
       SET ${fields.join(', ')},
           status = CASE WHEN status = 'approved' THEN 'pending_review' ELSE status END,
           updated_at = NOW()
       WHERE id = $${values.length}`,
      values
    );
    const payload = await getProviderPortalPayload(req.providerSession.providerId);
    res.json({ success: true, ...payload, review_required: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

