app.get('/api/bna/contact-communications', requireAdmin, async (req, res) => {
  const { lead_id, signup_id, student_id, contact_type } = req.query;
  const conditions = [];
  const params = [];
  const scopedProjectKey = opsScopeProjectKey(req);
  if (scopedProjectKey) {
    params.push(scopedProjectKey);
    conditions.push(`COALESCE(c.project_id, l.project_id, s.project_id, st.project_id, (SELECT id FROM bna_projects WHERE project_key = '${DEFAULT_PROJECT_KEY}' LIMIT 1)) = (SELECT id FROM bna_projects WHERE project_key = $${params.length} LIMIT 1)`);
  }

  if (lead_id) {
    params.push(lead_id);
    conditions.push(`c.lead_id = $${params.length}`);
  }
  if (signup_id) {
    params.push(signup_id);
    conditions.push(`c.signup_id = $${params.length}`);
  }
  if (student_id) {
    params.push(student_id);
    conditions.push(`c.student_id = $${params.length}`);
  }
  if (contact_type) {
    params.push(contact_type);
    conditions.push(`c.contact_type = $${params.length}`);
  }

  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

  try {
    const result = await pool.query(
      `SELECT c.*,
              l.parent_name AS lead_parent_name,
              l.lead_type AS lead_type,
              l.status AS lead_status,
              l.interest_level AS lead_interest_level,
              s.parent_name AS signup_parent_name,
              s.student_name AS signup_student_name,
              st.name AS student_name
       FROM bna_contact_communications c
       LEFT JOIN bna_parent_leads l ON l.id = c.lead_id
       LEFT JOIN signups s ON s.id = c.signup_id
       LEFT JOIN bna_students st ON st.id = c.student_id
       ${whereClause}
       ORDER BY c.occurred_at DESC, c.id DESC
       LIMIT 300`,
      params
    );
    res.json({ communications: result.rows });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/bna/contact-communications', requireAdmin, async (req, res) => {
  const body = req.body || {};
  const summary = String(body.summary || '').trim();
  if (!summary) return res.status(400).json({ error: 'summary is required' });

  try {
    let project = await resolveProjectForScopedWrite(req, body);
    let projectId = project.id;
    if (body.lead_id) {
      await assertProjectOwnedRowAccess(req, 'bna_parent_leads', body.lead_id);
      const linked = (await pool.query('SELECT project_id FROM bna_parent_leads WHERE id = $1', [body.lead_id])).rows[0];
      projectId = linked?.project_id || projectId;
    }
    if (body.signup_id) {
      await assertProjectOwnedRowAccess(req, 'signups', body.signup_id);
      const linked = (await pool.query('SELECT project_id FROM signups WHERE id = $1', [body.signup_id])).rows[0];
      projectId = linked?.project_id || projectId;
    }
    if (body.student_id) {
      await assertStudentAccess(req, body.student_id);
      const linked = (await pool.query('SELECT project_id FROM bna_students WHERE id = $1', [body.student_id])).rows[0];
      projectId = linked?.project_id || projectId;
    }
    const result = await pool.query(
      `INSERT INTO bna_contact_communications (
        project_id, contact_type, lead_id, signup_id, student_id, channel, direction,
        summary, body, follow_up_required, occurred_at, created_by, source,
        source_context, metadata
      ) VALUES (
        $1, COALESCE($2, 'lead'), $3, $4, $5, COALESCE($6, 'internal_note'), COALESCE($7, 'internal_note'),
        $8, $9, COALESCE($10::boolean, FALSE), COALESCE($11::timestamp, NOW()), $12, COALESCE($13, 'dashboard'),
        $14, $15
      )
      RETURNING *`,
      [
        projectId,
        body.contact_type || (body.lead_id ? 'lead' : body.signup_id ? 'signup' : 'general'),
        body.lead_id || null,
        body.signup_id || null,
        body.student_id || null,
        body.channel || 'internal_note',
        body.direction || 'internal_note',
        summary,
        body.body || null,
        Boolean(body.follow_up_required),
        body.occurred_at || null,
        body.created_by || req.opsUser || 'admin',
        body.source || 'dashboard',
        JSON.stringify(body.source_context || {}),
        JSON.stringify(body.metadata || {}),
      ]
    );
    res.json({ success: true, communication: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/bna/parent-access/link', requireAdmin, async (req, res) => {
  const body = req.body || {};
  try {
    const sendWhatsapp = Boolean(body.send_whatsapp || body.sendWhatsApp);
    if (sendWhatsapp && String(body.confirm || '').trim() !== 'SEND_WHATSAPP') {
      return res.status(400).json({
        error: 'WhatsApp login-link sends require confirm: SEND_WHATSAPP',
        hint: 'Use this only from an explicit Operations button/action.',
      });
    }

    const target = await resolveParentAccessTarget({
      contactType: body.contact_type || body.type,
      contactId: body.contact_id || body.id,
    });
    if (!target) return res.status(404).json({ error: 'Parent access target was not found' });
    const parentEmail = normalizeEmail(body.parent_email || target.parent_email);
    if (!parentEmail) return res.status(400).json({ error: 'This record does not have a parent email' });

    const link = await createParentMagicLink({
      parentEmail,
      req,
      requestedBy: req.opsUser || 'admin',
      metadata: {
        source: 'operations',
        contact_type: target.type,
        contact_id: target.row.id,
      },
      sendEmail: body.send_email !== false,
    });
    let whatsappResult = { ok: false, skipped: !sendWhatsapp };
    if (sendWhatsapp) {
      try {
        whatsappResult = await sendParentMagicLinkWhatsApp({
          target,
          parentEmail,
          url: link.url,
          req,
        });
      } catch (error) {
        whatsappResult = {
          ok: false,
          error: error.message,
          communication_id: error.communicationId || null,
          wapi_response: error.wapiResponse || null,
          compose_url: error.composeUrl || whatsAppComposeUrl(target.row.parent_phone, parentMagicLinkWhatsAppBody({
            parentName: target.row.parent_name || '',
            url: link.url,
          })),
        };
      }
    }

    res.json({
      success: true,
      parent_email: link.parent_email,
      url: link.url,
      expires_at: link.expires_at,
      email_sent: link.email_sent,
      email_error: link.email_error,
      whatsapp_sent: Boolean(whatsappResult.ok),
      whatsapp_error: whatsappResult.error || null,
      whatsapp_communication_id: whatsappResult.communication_id || null,
      whatsapp_compose_url: whatsappResult.compose_url || null,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

