app.post('/api/student-portal/goals/:id/checkoff', async (req, res) => {
  const code = String((req.body || {}).access_code || '').trim();
  const progressPercent = Math.max(0, Math.min(100, Math.round(Number((req.body || {}).progress_percent))));
  if (!Number.isFinite(progressPercent)) return res.status(400).json({ error: 'progress_percent must be a number' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const student = await getStudentForPortalCredential(req, res, code, client);
    if (!student) {
      await client.query('ROLLBACK');
      return;
    }

    const current = await getGoalBoardEvent(req.params.id, client);
    if (!current || Number(current.student_id) !== Number(student.id)) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Goal was not found for this student' });
    }
    let metadata = metadataAfterProgressUpdate(current, progressPercent);
    if (Object.prototype.hasOwnProperty.call(req.body || {}, 'reflection_note')) {
      metadata = goalBoardMetadataFromPayload({ reflection_note: (req.body || {}).reflection_note }, metadata);
    }

    const previousProgress = clampProgressPercent(current.progress_percent) || 0;
    const shouldNotifyParent = progressPercent >= 100 && previousProgress < 100;
    const autoAccess = automaticDeviceAccessForCompletion({ ...current, metadata }, progressPercent);
    let deviceAccessResult = null;
    let deviceAccessStatus = null;

    const result = await client.query(
      `UPDATE bna_accountability_events
       SET progress_percent = $3::numeric,
           goal_actual_value = CASE
             WHEN goal_target_value IS NULL THEN goal_actual_value
             ELSE ROUND((goal_target_value * $3::numeric / 100), 2)
           END,
           follow_up_required = $3::numeric < 100,
           metadata = $4,
           updated_at = NOW()
       WHERE id = $1
         AND student_id = $2
         AND event_type = 'student_goal'
       RETURNING *`,
      [req.params.id, student.id, progressPercent, JSON.stringify(metadata)]
    );
    if (!result.rows[0]) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Goal was not found for this student' });
    }

    if (autoAccess) {
      const deviceId = await getPreferredDeviceForStudent(student.id, client);
      if (deviceId) {
        deviceAccessResult = await applyDeviceAccessAction({
          deviceId,
          status: autoAccess.status,
          durationMinutes: autoAccess.durationMinutes,
          reason: autoAccess.reason,
          goalId: result.rows[0].id,
          approvedBy: 'student_checkoff',
        }, client);
        metadata = goalBoardMetadataFromPayload({
          goal_board: {
            consequence: {
              success_applied_at: autoAccess.appliedAt,
              success_applied_by: 'student_checkoff',
            },
          },
        }, metadata);
        const stamped = await client.query(
          `UPDATE bna_accountability_events
           SET metadata = $2,
               updated_at = NOW()
           WHERE id = $1
             AND event_type = 'student_goal'
           RETURNING *`,
          [result.rows[0].id, JSON.stringify(metadata)]
        );
        result.rows[0] = stamped.rows[0] || result.rows[0];
        deviceAccessStatus = 'applied';
      } else {
        deviceAccessStatus = 'no_device_configured';
      }
    }

    if (shouldNotifyParent) {
      await createParentActionNotification(client, {
        student,
        goal: result.rows[0],
        kind: 'goal_checkoff',
        checkoff: {
          goal_id: result.rows[0].id,
          goal_title: result.rows[0].title,
          progress_percent: progressPercent,
          note: String((req.body || {}).reflection_note || '').trim(),
        },
      });
      const refreshed = await getGoalBoardEvent(result.rows[0].id, client);
      if (refreshed) result.rows[0] = refreshed;
    }

    await client.query('COMMIT');
    res.json({
      success: true,
      goal: safeGoalBoardStudentView(result.rows[0]),
      automatic_device_access: autoAccess
        ? {
            status: deviceAccessStatus,
            requested_state: autoAccess.status,
            duration_minutes: autoAccess.durationMinutes,
            device: deviceAccessResult?.device || null,
            session: deviceAccessResult?.session || null,
          }
        : null,
    });
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch {
      // Ignore rollback failures; the original error is more useful.
    }
    res.status(500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/student-portal/goals/:id/day-checkoff', async (req, res) => {
  const code = String((req.body || {}).access_code || '').trim();
  const date = safeIsoDateInput((req.body || {}).date);
  const completed = Boolean((req.body || {}).completed);
  const note = Object.prototype.hasOwnProperty.call(req.body || {}, 'note')
    ? String((req.body || {}).note || '').trim().slice(0, 1000)
    : null;
  if (!date) return res.status(400).json({ error: 'A valid date is required' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const student = await getStudentForPortalCredential(req, res, code, client);
    if (!student) {
      await client.query('ROLLBACK');
      return;
    }

    const current = await getGoalBoardEvent(req.params.id, client);
    if (!current || Number(current.student_id) !== Number(student.id)) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Goal was not found for this student' });
    }

    const previousCheckin = (await client.query(
      `SELECT completed
       FROM bna_goal_board_checkins
       WHERE goal_id = $1
         AND date = $2::date
       LIMIT 1`,
      [current.id, date]
    )).rows[0] || null;

    await client.query(
      `INSERT INTO bna_goal_board_checkins (
         goal_id, student_id, date, completed, note, created_at, updated_at
       ) VALUES (
         $1, $2, $3::date, $4, $5, NOW(), NOW()
       )
       ON CONFLICT (goal_id, date)
       DO UPDATE SET
         completed = EXCLUDED.completed,
         note = CASE
           WHEN $6::boolean THEN EXCLUDED.note
           ELSE bna_goal_board_checkins.note
         END,
         updated_at = NOW()`,
      [
        current.id,
        student.id,
        date,
        completed,
        note,
        Object.prototype.hasOwnProperty.call(req.body || {}, 'note'),
      ]
    );

    let updatedGoal = await recalculateGoalProgressFromDailyCheckins(current.id, client);
    if (completed && !Boolean(previousCheckin?.completed)) {
      await createParentActionNotification(client, {
        student,
        goal: updatedGoal || current,
        kind: 'daily_checkoff',
        checkoff: {
          goal_id: current.id,
          goal_title: current.title,
          date,
          completed,
          note,
          progress_percent: updatedGoal?.progress_percent ?? current.progress_percent ?? null,
        },
      });
      updatedGoal = await getGoalBoardEvent(current.id, client) || updatedGoal;
    }
    await client.query('COMMIT');

    const [goalWithDaily] = await attachGoalBoardDailyCheckins([updatedGoal], {
      nextMeetingDate: await getStudentNextMeetingDate(student.id),
    });
    res.json({ success: true, goal: goalWithDaily });
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch {
      // Ignore rollback failures.
    }
    res.status(500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/student-portal/message-parent', async (req, res) => {
  const code = String((req.body || {}).access_code || '').trim();
  const message = String((req.body || {}).message || (req.body || {}).body || '').trim();
  const goalId = (req.body || {}).goal_id ? Number((req.body || {}).goal_id) : null;
  if (!message) return res.status(400).json({ error: 'Message is required' });
  if (message.length > 2000) return res.status(400).json({ error: 'Message is too long' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const student = await getStudentForPortalCredential(req, res, code, client);
    if (!student) {
      await client.query('ROLLBACK');
      return;
    }
    const notificationStudent = await hydrateStudentParentNotificationRecord(student, client);
    if (!normalizeEmail(notificationStudent.parent_email)) {
      await client.query('ROLLBACK');
      return res.status(400).json({ error: 'No parent email is linked to this student yet' });
    }

    let goal = null;
    if (goalId) {
      goal = await getGoalBoardEvent(goalId, client);
      if (!goal || Number(goal.student_id) !== Number(student.id)) {
        await client.query('ROLLBACK');
        return res.status(404).json({ error: 'Goal was not found for this student' });
      }
    }

    const saved = await createParentActionNotification(client, {
      student: notificationStudent,
      goal,
      kind: 'student_parent_message',
      message,
      checkoff: goal ? {
        goal_id: goal.id,
        goal_title: goal.title,
        progress_percent: goal.progress_percent ?? null,
      } : {},
    });
    await client.query('COMMIT');
    res.json({
      success: true,
      message: 'Message sent to the parent portal.',
      notification: parentActionNotificationView(saved.communication),
    });
  } catch (err) {
    try {
      await client.query('ROLLBACK');
    } catch {
      // Ignore rollback failures.
    }
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

