app.post('/api/parent-portal/help', async (req, res) => {
  const cookies = parseCookies(req);
  const body = req.body || {};
  const message = String(body.message || body.body || '').trim();
  const category = parentHelpCategory(body.category || body.topic);
  const studentId = body.student_id ? Number(body.student_id) : null;
  const sourceRoute = limitText(body.route || body.path || '', 300);
  const sourceViewport = body.viewport && typeof body.viewport === 'object'
    ? {
        width: Number(body.viewport.width || 0) || null,
        height: Number(body.viewport.height || 0) || null,
        device_scale_factor: Number(body.viewport.deviceScaleFactor || body.viewport.device_scale_factor || 0) || null,
      }
    : {};
  const sourceLanguage = body.language ? normalizeLanguage(body.language) : '';
  if (!message) return res.status(400).json({ error: 'Help message is required' });
  if (message.length > 3000) return res.status(400).json({ error: 'Help message is too long' });

  const client = await pool.connect();
  try {
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME], client);
    if (!session) return res.status(401).json({ error: 'Parent session is required' });
    const records = await findParentAccessRecords(session.parentEmail, client);
    let student = null;
    if (studentId) {
      student = await getParentPortalStudentForSession(session.parentEmail, studentId, client);
      if (!student) return res.status(404).json({ error: 'Student was not found for this parent session' });
    }
    const tags = parentInteractionTags('portal_help', category, message);
    const summary = `${category === 'problem' ? 'Parent problem report' : category === 'technology' ? 'Parent technology help' : 'Parent help'}: ${records.students[0]?.parent_name || session.parentEmail}`;
    const sourceContext = {
      source: 'parent_portal_help',
      category,
      student_id: student?.id || null,
      route: sourceRoute || null,
      viewport: sourceViewport,
      language: sourceLanguage || null,
    };
    const communication = (await client.query(
      `INSERT INTO bna_contact_communications (
         contact_type, signup_id, student_id, channel, direction, summary, body,
         follow_up_required, occurred_at, created_by, source, source_context, metadata
       ) VALUES (
         $1, $2, $3, 'email', 'inbound', $4, $5,
         TRUE, NOW(), 'parent_portal', 'dashboard', $6, $7
       )
       RETURNING *`,
      [
        student ? 'student' : records.signups[0]?.id ? 'signup' : 'general',
        records.signups[0]?.id || null,
        student?.id || records.students[0]?.id || null,
        summary,
        message,
        JSON.stringify(sourceContext),
        JSON.stringify({
          parent_email: session.parentEmail,
          category,
          internal_tags: tags,
          student_id: student?.id || null,
          route: sourceRoute || null,
          viewport: sourceViewport,
          language: sourceLanguage || null,
        }),
      ]
    )).rows[0];

    await mergeParentRecordTags(session.parentEmail, tags, client);
    if (category === 'problem') {
      const bnaProject = await upsertProject({
        projectKey: DEFAULT_PROJECT_KEY,
        name: 'BNA',
        shortName: 'BNA',
        description: 'Bnei Neviim Academy operations, students, content, contacts, and accounting.',
      }, client);
      const ticketTitle = limitText(`Parent report problem: ${records.students[0]?.parent_name || session.parentEmail}`, 180);
      const ticket = (await client.query(
        `INSERT INTO bna_support_tickets (
           project_id, title, description, severity, status, category,
           reporter_name, reporter_role, assigned_to, source, source_context, created_by
         )
         VALUES ($1, $2, $3, 'normal', 'open', 'other', $4, 'parent', 'Shloimie', 'dashboard', $5::jsonb, 'parent_portal')
        RETURNING *`,
        [
          bnaProject.id,
          ticketTitle,
          message,
          records.students[0]?.parent_name || session.parentEmail,
          JSON.stringify({
            ...sourceContext,
            parent_email: session.parentEmail,
            communication_id: communication.id,
            internal_tags: tags,
            classification: 'parent_report_problem_review_ticket',
            codex_task_created: false,
          }),
        ]
      )).rows[0];

      let emailSent = false;
      let emailError = '';
      if (PARENT_HELP_EMAIL) {
        const emailText = [
          'Parent portal problem report',
          '',
          `Parent: ${session.parentEmail}`,
          student ? `Student: ${student.name}` : '',
          `Category: ${category}`,
          sourceRoute ? `Route: ${sourceRoute}` : '',
          `Communication: #${communication.id}`,
          `Support ticket: #${ticket.id}`,
          '',
          message,
        ].filter(Boolean).join('\n');
        const result = await sendGmailMessage({
          to: PARENT_HELP_EMAIL,
          subject: 'BNA parent problem report',
          text: emailText,
          html: emailText.replace(/\n/g, '<br>'),
        }).then((gmailResult) => ({ ok: true, id: gmailResult.data?.id || '' }))
          .catch((error) => ({ ok: false, error: error instanceof Error ? error.message : String(error) }));
        emailSent = Boolean(result.ok);
        emailError = result.error || '';
      }

      return res.json({
        success: true,
        message: 'Problem report saved for review.',
        communication_id: communication.id,
        support_ticket_id: ticket.id,
        task_id: null,
        codex_task_created: false,
        email_sent: emailSent,
        email_error: emailError,
        tags,
      });
    }
    const task = await createTaskFromText({
      title: `${category === 'technology' ? 'Parent technology help' : 'Parent help'}: ${records.students[0]?.parent_name || session.parentEmail}`,
      raw_text: message,
      notes: [
        `Parent: ${session.parentEmail}`,
        student ? `Student: ${student.name}` : '',
        `Category: ${category}`,
        `Communication #${communication.id}`,
        '',
        message,
      ].filter(Boolean).join('\n'),
      stage: 'assigned',
      category: parentHelpTaskCategory(category),
      urgency: category === 'technology' || category === 'access' ? 'today' : 'this_week',
      assigned_to: 'Shloimie',
      source: 'web',
      created_by: 'parent_portal',
      source_context: {
        parent_email: session.parentEmail,
        student_id: student?.id || null,
        communication_id: communication.id,
        route: sourceRoute || null,
        viewport: sourceViewport,
        language: sourceLanguage || null,
        internal_tags: tags,
      },
      ai_parsed: {
        parser: 'parent-portal-help-v1',
        kind: 'parent_help',
        category,
        internal_tags: tags,
      },
    }, {}, client);

    let emailSent = false;
    let emailError = '';
    if (PARENT_HELP_EMAIL) {
      const emailText = [
        'Parent portal help request',
        '',
        `Parent: ${session.parentEmail}`,
        student ? `Student: ${student.name}` : '',
        `Category: ${category}`,
        `Communication: #${communication.id}`,
        `Task: #${task.id}`,
        '',
        message,
      ].filter(Boolean).join('\n');
      const result = await sendGmailMessage({
        to: PARENT_HELP_EMAIL,
        subject: `BNA parent help: ${category}`,
        text: emailText,
        html: emailText.replace(/\n/g, '<br>'),
      }).then((gmailResult) => ({ ok: true, id: gmailResult.data?.id || '' }))
        .catch((error) => ({ ok: false, error: error instanceof Error ? error.message : String(error) }));
      emailSent = Boolean(result.ok);
      emailError = result.error || '';
    }

    res.json({
      success: true,
      message: 'Help request sent.',
      communication_id: communication.id,
      task_id: task.id,
      email_sent: emailSent,
      email_error: emailError,
      tags,
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

app.post('/api/parent-portal/provider-messages', async (req, res) => {
  const cookies = parseCookies(req);
  const providerId = Number((req.body || {}).provider_id || (req.body || {}).providerId);
  const serviceId = (req.body || {}).service_id || (req.body || {}).serviceId ? Number((req.body || {}).service_id || (req.body || {}).serviceId) : null;
  const studentId = (req.body || {}).student_id || (req.body || {}).studentId ? Number((req.body || {}).student_id || (req.body || {}).studentId) : null;
  const body = String((req.body || {}).body || (req.body || {}).message || '').trim();
  const subject = limitText((req.body || {}).subject || 'Provider inquiry', 220) || 'Provider inquiry';
  if (!Number.isFinite(providerId) || providerId <= 0) return res.status(400).json({ error: 'A valid provider_id is required' });
  if (serviceId !== null && !Number.isFinite(serviceId)) return res.status(400).json({ error: 'service_id must be numeric' });
  if (studentId !== null && !Number.isFinite(studentId)) return res.status(400).json({ error: 'student_id must be numeric' });
  if (!body) return res.status(400).json({ error: 'Message body is required' });
  if (body.length > 3000) return res.status(400).json({ error: 'Message body is too long' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const session = await getValidParentSession(cookies[PARENT_SESSION_COOKIE_NAME], client);
    if (!session) {
      await client.query('ROLLBACK');
      return res.status(401).json({ error: 'Parent session is required' });
    }
    const records = await findParentAccessRecords(session.parentEmail, client);
    let student = null;
    if (studentId) {
      student = await getParentPortalStudentForSession(session.parentEmail, studentId, client);
      if (!student) {
        await client.query('ROLLBACK');
        return res.status(404).json({ error: 'Student was not found for this parent session' });
      }
    }
    const provider = (await client.query(
      `SELECT id, provider_name, can_receive_messages
       FROM bna_service_providers
       WHERE id = $1
         AND status = 'approved'
         AND public_listing_enabled IS NOT FALSE
       LIMIT 1`,
      [providerId]
    )).rows[0];
    if (!provider || provider.can_receive_messages === false) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Provider is not available for parent messages' });
    }
    let service = null;
    if (serviceId) {
      service = (await client.query(
        `SELECT id, title
         FROM bna_provider_services
         WHERE id = $1
           AND provider_id = $2
           AND status = 'approved'
         LIMIT 1`,
        [serviceId, providerId]
      )).rows[0];
      if (!service) {
        await client.query('ROLLBACK');
        return res.status(404).json({ error: 'Provider service is not available' });
      }
    }
    const message = (await client.query(
      `INSERT INTO bna_provider_messages (
         provider_id, service_id, parent_email, student_id, direction, channel,
         subject, body, status, source, source_context, metadata
       ) VALUES (
         $1, $2, $3, $4, 'parent_to_provider', 'portal',
         $5, $6, 'open', 'parent_portal', $7::jsonb, $8::jsonb
       )
       RETURNING *`,
      [
        providerId,
        service?.id || null,
        session.parentEmail,
        student?.id || records.students[0]?.id || null,
        subject,
        body,
        JSON.stringify({ source: 'parent_provider_directory', service_id: service?.id || null }),
        JSON.stringify({
          provider_name: provider.provider_name,
          service_title: service?.title || null,
          parent_email: session.parentEmail,
        }),
      ]
    )).rows[0];
    await client.query(
      `INSERT INTO bna_contact_communications (
         contact_type, student_id, channel, direction, summary, body,
         follow_up_required, occurred_at, created_by, source, source_context, metadata
       ) VALUES (
         'general', $1, 'email', 'inbound', $2, $3,
         TRUE, NOW(), 'parent_portal', 'dashboard', $4, $5
       )`,
      [
        student?.id || records.students[0]?.id || null,
        `Parent/provider message: ${provider.provider_name}`,
        body,
        JSON.stringify({ source: 'parent_provider_message', provider_id: providerId, provider_message_id: message.id }),
        JSON.stringify({ parent_email: session.parentEmail, provider_name: provider.provider_name, service_title: service?.title || null }),
      ]
    ).catch(() => {});
    await client.query('COMMIT');
    res.json({ success: true, message });
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    res.status(err.statusCode || 500).json({ error: err.message });
  } finally {
    client.release();
  }
});

