app.post('/api/bna/accountability/enrich-question-sources', requireAdmin, async (req, res) => {
  const limit = Math.max(1, Math.min(Number((req.body || {}).limit) || 25, 100));
  const force = Boolean((req.body || {}).force);
  try {
    const conditions = [`event_type = 'question'`];
    const params = [];
    appendScopeCondition(req, conditions, params, 'project_id');
    params.push(limit);
    const rows = (await pool.query(
      `SELECT id
       FROM bna_accountability_events
       WHERE ${conditions.join(' AND ')}
       ORDER BY COALESCE(occurred_at, created_at) DESC, id DESC
       LIMIT $${params.length}`,
      params
    )).rows;
    const enriched = [];
    const failed = [];
    for (const row of rows) {
      try {
        // eslint-disable-next-line no-await-in-loop
        const result = await enrichQuestionEventWithSefariaSources(row.id, { force });
        enriched.push({ id: row.id, refreshed: result.refreshed, sources: result.question.sources.length });
      } catch (error) {
        failed.push({ id: row.id, error: error.message });
      }
    }
    res.json({ success: failed.length === 0, enriched, failed });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

