app.get('/api/bna/payment-intake', requireAdmin, async (req, res) => {
  const { status } = req.query;
  const params = [];
  const conditions = [];
  const scopedProjectKey = opsScopeProjectKey(req);
  if (scopedProjectKey) {
    params.push(scopedProjectKey);
    conditions.push(`COALESCE(i.project_id, s.project_id, (SELECT id FROM bna_projects WHERE project_key = '${DEFAULT_PROJECT_KEY}' LIMIT 1)) = (SELECT id FROM bna_projects WHERE project_key = $${params.length} LIMIT 1)`);
  }

  if (status) {
    params.push(status);
    conditions.push(`i.status = $${params.length}`);
  }
  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

  try {
    const result = await pool.query(
      `SELECT i.*, row_to_json(s.*) AS signup
       FROM bna_payment_intake i
       LEFT JOIN signups s ON s.id = i.signup_id
       ${whereClause}
       ORDER BY i.received_at DESC, i.created_at DESC
       LIMIT 100`,
      params
    );
    res.json({ intake: result.rows });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/bna/payment-intake/reconcile-paid', requireAdmin, async (req, res) => {
  const records = Array.isArray(req.body?.records) ? req.body.records : [];
  if (!records.length) {
    return res.status(400).json({ error: 'records array is required' });
  }

  const client = await pool.connect();
  const results = [];

  try {
    await client.query('BEGIN');
    await client.query('ALTER TABLE signups ALTER COLUMN parent_email DROP NOT NULL');

    for (const input of records) {
      const intakeId = Number(input.intake_id || input.intakeId || 0);
      const studentName = String(input.student_name || input.studentName || '').trim();
      const parentName = String(input.parent_name || input.parentName || '').trim();
      const parentEmail = String(input.parent_email || input.parentEmail || '').trim() || null;
      const parentPhone = String(input.parent_phone || input.parentPhone || '').trim() || null;
      const method = String(input.method || '').trim();
      const amount = Number(input.amount || 0);
      const paidAt = input.paid_at || input.paidAt || null;
      const dueDate = input.due_date || input.dueDate || null;
      const note = String(input.note || input.notes || '').trim()
        || 'Admin-created from paid intake; missing official signup fields intentionally left blank.';

      if (!intakeId || !studentName || !parentName || !amount || !method || !paidAt || !dueDate) {
        throw new Error('Each record requires intake_id, student_name, parent_name, amount, method, paid_at, and due_date');
      }

      const student = (await client.query(
        `SELECT *
         FROM bna_students
         WHERE lower(name) = lower($1)
           AND status <> 'inactive'
         ORDER BY id DESC
         LIMIT 1`,
        [studentName]
      )).rows[0];

      if (!student) {
        throw new Error(`No active student found for ${studentName}`);
      }

      const existingSignup = student.signup_id
        ? (await client.query('SELECT * FROM signups WHERE id = $1', [student.signup_id])).rows[0]
        : (await client.query(
            'SELECT * FROM signups WHERE lower(student_name) = lower($1) ORDER BY id DESC LIMIT 1',
            [studentName]
          )).rows[0];

      const adminTags = ['parent', 'bna', 'admin_intake'];
      let signup;
      let signupCreated = false;

      if (existingSignup) {
        signup = (await client.query(
          `UPDATE signups
           SET parent_name = COALESCE(NULLIF($2, ''), parent_name),
               parent_email = COALESCE($3, parent_email),
               parent_phone = COALESCE($4, parent_phone),
               student_name = $5,
               payment_method = $6,
               payment_status = 'paid',
               payment_amount = $7,
               payment_currency = 'ILS',
               payment_interval_days = COALESCE(payment_interval_days, $8),
               payment_due_date = $9,
               last_payment_at = $10,
               status = COALESCE(NULLIF(status, ''), 'new'),
               tags = (SELECT ARRAY(SELECT DISTINCT unnest(COALESCE(tags, '{}') || $11::text[]))),
               notes = CASE
                 WHEN notes IS NULL OR notes = '' THEN $12
                 WHEN notes LIKE '%' || $12 || '%' THEN notes
                 ELSE notes || E'\n' || $12
               END,
               updated_at = NOW()
           WHERE id = $1
           RETURNING *`,
          [
            existingSignup.id,
            parentName,
            parentEmail,
            parentPhone,
            studentName,
            method,
            amount,
            DEFAULT_PAYMENT_INTERVAL_DAYS,
            dueDate,
            paidAt,
            adminTags,
            note,
          ]
        )).rows[0];
      } else {
        signup = (await client.query(
          `INSERT INTO signups (
             parent_name, parent_email, parent_phone, student_name,
             payment_method, payment_status, payment_amount, payment_currency,
             payment_interval_days, payment_due_date, last_payment_at,
             status, tags, notes, created_at, updated_at
           ) VALUES ($1,$2,$3,$4,$5,'paid',$6,'ILS',$7,$8,$9,'new',$10::text[],$11,NOW(),NOW())
           RETURNING *`,
          [
            parentName,
            parentEmail,
            parentPhone,
            studentName,
            method,
            amount,
            DEFAULT_PAYMENT_INTERVAL_DAYS,
            dueDate,
            paidAt,
            adminTags,
            note,
          ]
        )).rows[0];
        signupCreated = true;
      }

      await client.query(
        `UPDATE bna_students
         SET signup_id = $1,
             parent_name = COALESCE(NULLIF($2, ''), parent_name),
             parent_email = COALESCE($3, parent_email),
             parent_phone = COALESCE($4, parent_phone),
             updated_at = NOW()
         WHERE id = $5`,
        [signup.id, parentName, parentEmail, parentPhone, student.id]
      );

      const existingPayment = (await client.query(
        `SELECT id
         FROM bna_payment_log
         WHERE signup_id = $1
           AND payment_type = 'registration'
           AND amount = $2
           AND method = $3
           AND status = 'completed'
           AND received_at::date = $4::date
         ORDER BY id DESC
         LIMIT 1`,
        [signup.id, amount, method, paidAt]
      )).rows[0];

      let paymentLogId = existingPayment?.id || null;
      if (!paymentLogId) {
        paymentLogId = (await client.query(
          `INSERT INTO bna_payment_log (
             signup_id, payment_type, amount, currency, method,
             received_by, received_at, notes, status
           ) VALUES ($1,'registration',$2,'ILS',$3,'admin_paid_intake_reconcile',$4,$5,'completed')
           RETURNING id`,
          [signup.id, amount, method, paidAt, note]
        )).rows[0].id;
      }

      const intake = (await client.query(
        `UPDATE bna_payment_intake
         SET signup_id = $1,
             parent_name = COALESCE(NULLIF($2, ''), parent_name),
             parent_email = COALESCE($3, parent_email),
             parent_phone = COALESCE($4, parent_phone),
             student_name = $5,
             amount = $6,
             method = $7,
             status = 'matched',
             received_at = COALESCE(received_at, $8),
             matched_at = COALESCE(matched_at, NOW()),
             notes = CASE
               WHEN notes IS NULL OR notes = '' THEN $9
               WHEN notes LIKE '%' || $9 || '%' THEN notes
               ELSE notes || E'\n' || $9
             END,
             updated_at = NOW()
         WHERE id = $10
         RETURNING id, status, signup_id`,
        [
          signup.id,
          parentName,
          parentEmail,
          parentPhone,
          studentName,
          amount,
          method,
          paidAt,
          note,
          intakeId,
        ]
      )).rows[0];

      if (!intake) {
        throw new Error(`No payment intake record found for id ${intakeId}`);
      }

      results.push({
        intake_id: intake.id,
        intake_status: intake.status,
        student_id: student.id,
        student_name: studentName,
        signup_id: signup.id,
        signup_created: signupCreated,
        payment_log_id: paymentLogId,
      });
    }

    const remainingNeedsSignup = (await client.query(
      `SELECT id, parent_name, student_name, amount, method
       FROM bna_payment_intake
       WHERE status = 'needs_signup'
       ORDER BY id`
    )).rows;

    await client.query('COMMIT');
    res.json({ success: true, results, remaining_needs_signup: remainingNeedsSignup });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: err.message, stack: err.stack });
  } finally {
    client.release();
  }
});

app.post('/api/bna/payment-intake', requireAdmin, async (req, res) => {
  const {
    signup_id,
    parent_name,
    parent_email,
    parent_phone,
    student_name,
    amount,
    currency,
    method = 'unknown',
    payment_type = 'registration',
    green_invoice_id,
    green_invoice_url,
    status = 'unmatched',
    source = 'manual',
    source_context,
    received_at,
    notes,
  } = req.body || {};

  try {
    const project = await resolveProjectForScopedWrite(req, req.body || {});
    if (signup_id) await assertProjectOwnedRowAccess(req, 'signups', signup_id);
    const signup = signup_id ? (await pool.query('SELECT project_id FROM signups WHERE id = $1', [signup_id])).rows[0] : null;
    let ghlContactId = null;
    if (GHL_PIT_TOKEN && (parent_email || parent_phone || parent_name)) {
      try {
        const nameParts = String(parent_name || 'BNA Parent').trim().split(/\s+/);
        const firstName = nameParts.shift() || 'BNA';
        const lastName = nameParts.join(' ') || 'Parent';
        ghlContactId = await findOrCreateGHLContact(
          parent_email || `${String(parent_phone || Date.now()).replace(/\D/g, '')}@bna.payment-intake`,
          firstName,
          lastName,
          parent_phone || '',
          { tags: ['BNA Parent', 'Payment Intake'] }
        );
        await addTagToContact(ghlContactId, 'BNA Parent');
        await addTagToContact(ghlContactId, 'Payment Intake');
      } catch (ghlErr) {
        console.error('Payment intake GHL sync error:', ghlErr);
      }
    }

    const intake = await createPaymentIntakeRecord({
      project_id: signup?.project_id || project.id,
      signup_id,
      parent_name,
      parent_email,
      parent_phone,
      student_name,
      amount,
      currency,
      method,
      payment_type,
      green_invoice_id,
      green_invoice_url,
      ghl_contact_id: ghlContactId,
      status,
      source,
      source_context,
      received_at,
      notes,
    });

    res.json({ success: true, intake });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.patch('/api/bna/payment-intake/:id', requireAdmin, async (req, res) => {
  const { id } = req.params;
  const allowedFields = [
    'signup_id',
    'parent_name',
    'parent_email',
    'parent_phone',
    'student_name',
    'amount',
    'currency',
    'method',
    'payment_type',
    'green_invoice_id',
    'green_invoice_url',
    'ghl_contact_id',
    'status',
    'received_at',
    'notes',
  ];
  const fields = [];
  const values = [];

  for (const [key, value] of Object.entries(req.body || {})) {
    if (!allowedFields.includes(key)) continue;
    values.push(value);
    fields.push(`${key} = $${values.length}`);
  }

  if (!fields.length) {
    return res.status(400).json({ error: 'No valid payment intake fields provided' });
  }

  values.push(id);

  try {
    await assertProjectOwnedRowAccess(req, 'bna_payment_intake', id);
    if (Object.prototype.hasOwnProperty.call(req.body || {}, 'signup_id') && req.body.signup_id) {
      await assertProjectOwnedRowAccess(req, 'signups', req.body.signup_id);
    }
    const result = await pool.query(
      `UPDATE bna_payment_intake
       SET ${fields.join(', ')}, updated_at = NOW()
       WHERE id = $${values.length}
       RETURNING *`,
      values
    );
    res.json({ success: true, intake: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

