app.get('/api/bna/content-jobs', requireAdmin, async (req, res) => {
  const { status } = req.query;
  const params = [];
  const conditions = [];
  appendScopeCondition(req, conditions, params, 'j.project_id');

  if (status) {
    params.push(status);
    conditions.push(`j.status = $${params.length}`);
  }
  const whereClause = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

  try {
    const result = await pool.query(
      `SELECT j.*,
        p.project_key,
        p.name AS project_name,
        p.short_name AS project_short_name,
        COALESCE(
          json_agg(o.* ORDER BY o.created_at ASC) FILTER (WHERE o.id IS NOT NULL),
          '[]'
        ) AS outputs
       FROM bna_content_jobs j
       LEFT JOIN bna_projects p ON p.id = j.project_id
       LEFT JOIN bna_content_outputs o ON o.job_id = j.id
       ${whereClause}
       GROUP BY j.id, p.id
       ORDER BY j.created_at DESC
       LIMIT 100`,
      params
    );
    res.json({ jobs: result.rows });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

