app.post('/api/bna/wapi/sync', requireAdmin, async (req, res) => {
  try {
    const result = await runWapiMessageSync({ req, body: req.body || {} });
    res.json(result);
  } catch (err) {
    const statusCode = Number(err.statusCode || 500);
    res.status(statusCode >= 400 && statusCode < 600 ? statusCode : 500).json({
      success: false,
      error: err.message,
      sync_run: err.syncRun || null,
      wapi_response: err.wapiResponse || null,
    });
  }
});

app.post('/api/bna/contact-communications/send-whatsapp', requireAdmin, async (req, res) => {
  const body = req.body || {};
  const messageBody = String(body.body || body.message || '').trim();
  const confirm = String(body.confirm || '').trim();
  if (!messageBody) return res.status(400).json({ error: 'body or message is required' });
  if (confirm !== 'SEND_WHATSAPP') {
    return res.status(400).json({
      error: 'WhatsApp sends require confirm: SEND_WHATSAPP',
      hint: 'Use the endpoint for deliberate sends only. The message is not sent until confirm is present.',
    });
  }

  let recipient = null;
  let attempt = null;
  try {
    recipient = await resolveWapiOutboundRecipient(body);
    attempt = await createOutboundWapiCommunicationAttempt({
      recipient,
      messageBody,
      source: body.source || 'dashboard',
      createdBy: body.created_by || req.opsUser || 'admin',
      metadata: body.metadata || {},
    });
    const sendResult = await sendWapiTextMessage({
      to: recipient.to,
      body: messageBody,
      typingTime: body.typing_time || body.typingTime || 0,
      noLinkPreview: body.no_link_preview ?? body.noLinkPreview ?? true,
      timeoutMs: body.timeout_ms || body.timeoutMs || WAPI_SEND_TIMEOUT_MS,
    });
    const communication = await updateOutboundWapiCommunicationResult(attempt.id, {
      sendResult,
      summary: `WhatsApp sent to ${recipient.name || recipient.phone || recipient.to}`.slice(0, 240),
    });
    res.json({
      success: true,
      sent: true,
      recipient,
      communication,
      wapi: sendResult.response,
    });
  } catch (err) {
    let communication = null;
    if (attempt?.id) {
      communication = await updateOutboundWapiCommunicationResult(attempt.id, { error: err }).catch(() => null);
    }
    const statusCode = Number(err.statusCode || 500);
    res.status(statusCode >= 400 && statusCode < 600 ? statusCode : 500).json({
      success: false,
      sent: false,
      delivery_status: wapiErrorDeliveryStatus(err),
      error: err.message,
      wapi_response: err.wapiResponse || null,
      recipient,
      communication,
    });
  }
});

