app.get('/operations-access', async (req, res) => {
  const token = String(req.query.token || '').trim();
  if (!token) return res.redirect('/operations-login.html?access=missing');

  try {
    const redeemed = await redeemOpsAccessLink(token);
    if (!redeemed) return res.redirect('/operations-login.html?access=expired');
    setSessionCookie(res, redeemed.sessionId);
    return res.redirect(redeemed.returnTo);
  } catch (err) {
    console.error('Operations access link error:', err);
    return res.redirect('/operations-login.html?access=error');
  }
});

