app.get('/api/bna/agent-fleet/status', requireAdmin, async (req, res) => {
  try {
    const runtimes = (await pool.query(
      `SELECT *,
              CASE
                WHEN last_seen_at IS NULL THEN true
                ELSE last_seen_at < NOW() - (COALESCE(stale_after_ms, 180000) * INTERVAL '1 millisecond')
              END AS stale
       FROM bna_agent_runtime_status
       WHERE agent_key IN ('codex-fleet', 'codex-watchdog')
       ORDER BY last_seen_at DESC`
    )).rows || [];
    const runtime = runtimes.find((row) => row.agent_key === 'codex-fleet') || null;
    const watchdogRuntime = runtimes.find((row) => row.agent_key === 'codex-watchdog') || null;

    const queue = (await pool.query(
      `WITH machine_tasks AS (
         SELECT *,
                (
                  LOWER(COALESCE(assigned_to, '')) LIKE '%codex%'
                  OR LOWER(COALESCE(assigned_to, '')) LIKE '%kimi%'
                  OR LOWER(COALESCE(assigned_to, '')) LIKE '%system%'
                ) AS is_machine
         FROM bna_tasks
       )
       SELECT
         COUNT(*) FILTER (
           WHERE is_machine
             AND COALESCE(stage, '') NOT IN ('done', 'archive')
             AND completed_at IS NULL
             AND verified_at IS NULL
         )::int AS pending,
         COUNT(*) FILTER (
           WHERE is_machine
             AND stage = 'in_progress'
             AND completed_at IS NULL
             AND verified_at IS NULL
         )::int AS in_progress,
         COUNT(*) FILTER (
           WHERE is_machine
             AND urgency IN ('urgent', 'today')
             AND COALESCE(stage, '') NOT IN ('done', 'archive')
             AND completed_at IS NULL
             AND verified_at IS NULL
         )::int AS urgent_today,
         COUNT(*) FILTER (
           WHERE is_machine
             AND (completed_at IS NOT NULL OR verified_at IS NOT NULL OR stage = 'done')
         )::int AS completed
       FROM machine_tasks`
    )).rows[0] || {};

    const latestTask = (await pool.query(
      `SELECT id, title, stage, urgency, assigned_to, created_at, started_at
       FROM bna_tasks
       WHERE (
         LOWER(COALESCE(assigned_to, '')) LIKE '%codex%'
         OR LOWER(COALESCE(assigned_to, '')) LIKE '%kimi%'
         OR LOWER(COALESCE(assigned_to, '')) LIKE '%system%'
       )
       AND COALESCE(stage, '') NOT IN ('done', 'archive')
       AND completed_at IS NULL
       AND verified_at IS NULL
       ORDER BY
         CASE urgency WHEN 'urgent' THEN 1 WHEN 'today' THEN 2 WHEN 'this_week' THEN 3 ELSE 4 END,
         created_at DESC
       LIMIT 1`
    )).rows[0] || null;

    const formatRuntime = (row) => row ? {
      status: row.status,
      pid: row.pid,
      mode: row.mode,
      host: row.host,
      started_at: row.started_at,
      last_seen_at: row.last_seen_at,
      stale: Boolean(row.stale),
      current_task_id: row.current_task_id,
      queue_size: row.queue_size,
      ready_count: row.ready_count,
      details: row.details || {},
    } : {
      status: 'unknown',
      stale: true,
      details: {},
    };

    res.json({
      success: true,
      fleet: formatRuntime(runtime),
      watchdog: formatRuntime(watchdogRuntime),
      queue: {
        pending: Number(queue.pending || 0),
        in_progress: Number(queue.in_progress || 0),
        urgent_today: Number(queue.urgent_today || 0),
        completed: Number(queue.completed || 0),
        latest_task: latestTask,
      },
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/bna/agent-fleet/status', requireAdmin, async (req, res) => {
  const {
    agent_key = 'codex-fleet',
    status = 'running',
    pid = null,
    mode = null,
    host = null,
    started_at = null,
    stale_after_ms = 180000,
    current_task_id = null,
    queue_size = null,
    ready_count = null,
    details = {},
  } = req.body || {};
  const allowedStatus = ['unknown', 'running', 'stopped', 'error'].includes(String(status))
    ? String(status)
    : 'unknown';

  try {
    const result = await pool.query(
      `INSERT INTO bna_agent_runtime_status (
         agent_key, status, pid, mode, host, started_at, last_seen_at,
         stale_after_ms, current_task_id, queue_size, ready_count, details, updated_at
       )
       VALUES ($1, $2, $3, $4, $5, $6, NOW(), $7, $8, $9, $10, $11::jsonb, NOW())
       ON CONFLICT (agent_key) DO UPDATE SET
         status = EXCLUDED.status,
         pid = EXCLUDED.pid,
         mode = EXCLUDED.mode,
         host = EXCLUDED.host,
         started_at = COALESCE(EXCLUDED.started_at, bna_agent_runtime_status.started_at),
         last_seen_at = NOW(),
         stale_after_ms = EXCLUDED.stale_after_ms,
         current_task_id = EXCLUDED.current_task_id,
         queue_size = EXCLUDED.queue_size,
         ready_count = EXCLUDED.ready_count,
         details = EXCLUDED.details,
         updated_at = NOW()
       RETURNING *`,
      [
        String(agent_key || 'codex-fleet').slice(0, 120),
        allowedStatus,
        pid === null || pid === undefined ? null : Number(pid),
        mode ? String(mode).slice(0, 80) : null,
        host ? String(host).slice(0, 160) : null,
        started_at || null,
        Number(stale_after_ms || 180000),
        current_task_id === null || current_task_id === undefined ? null : Number(current_task_id),
        queue_size === null || queue_size === undefined ? null : Number(queue_size),
        ready_count === null || ready_count === undefined ? null : Number(ready_count),
        JSON.stringify(details || {}),
      ]
    );
    res.json({ success: true, status: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/bna/projects', requireAdmin, async (req, res) => {
  try {
    const scopedProjectKey = opsScopeProjectKey(req);
    const params = [];
    let query = 'SELECT * FROM bna_projects WHERE status <> \'archived\'';
    if (scopedProjectKey) {
      query += ' AND project_key = $1';
      params.push(scopedProjectKey);
    }
    query += ' ORDER BY CASE project_key WHEN \'bna\' THEN 1 WHEN \'one_time_mishnah_class\' THEN 2 ELSE 3 END, name ASC';
    let result = await pool.query(query, params);
    if (!result.rows.length && !scopedProjectKey) {
      await ensureDefaultProjects();
      result = await pool.query(query, params);
    }
    res.json({ projects: result.rows });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.get('/api/bna/people', requireAdmin, async (req, res) => {
  try {
    const scopedProjectKey = opsScopeProjectKey(req);
    const params = [];
    let query = `
      SELECT pm.*,
             p.project_key,
             p.name AS project_name,
             p.short_name AS project_short_name
      FROM bna_project_members pm
      JOIN bna_projects p ON p.id = pm.project_id
      WHERE p.status <> 'archived'
        AND COALESCE(pm.active, TRUE) = TRUE`;
    if (scopedProjectKey) {
      params.push(scopedProjectKey);
      query += ` AND p.project_key = $${params.length}`;
    }
    query += `
      ORDER BY
        CASE p.project_key WHEN 'bna' THEN 1 WHEN 'one_time_mishnah_class' THEN 2 ELSE 3 END,
        CASE pm.access_level WHEN 'owner' THEN 1 WHEN 'manager' THEN 2 WHEN 'member' THEN 3 ELSE 4 END,
        pm.person_name ASC`;
    const result = await pool.query(query, params);
    res.json({ people: result.rows.map(internalPersonView) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.post('/api/bna/people', requireAdmin, async (req, res) => {
  try {
    const body = req.body || {};
    const personName = String(body.person_name || body.name || '').trim();
    if (!personName) return res.status(400).json({ error: 'person_name is required' });

    const project = await resolveProjectFromInput(
      { project_key: body.project_key || body.project || DEFAULT_PROJECT_KEY },
      pool
    );
    assertProjectAccess(req, project);

    const metadata = {
      ...(body.metadata && typeof body.metadata === 'object' ? body.metadata : {}),
      email: normalizeEmail(body.email) || undefined,
      phone: String(body.phone || '').trim() || undefined,
      notes: String(body.notes || '').trim() || undefined,
      source: body.source || 'dashboard',
      audience: 'internal',
    };
    Object.keys(metadata).forEach((key) => {
      if (metadata[key] === undefined || metadata[key] === '') delete metadata[key];
    });

    const person = await ensureProjectMember(project, personName, {
      role: String(body.role || 'school user').trim() || 'school user',
      access_level: safeProjectMemberAccessLevel(body.access_level),
      telegram_chat_id: body.telegram_chat_id || null,
      login_username: body.login_username || null,
      metadata,
    }, pool);

    const row = (await pool.query(
      `SELECT pm.*,
              p.project_key,
              p.name AS project_name,
              p.short_name AS project_short_name
       FROM bna_project_members pm
       JOIN bna_projects p ON p.id = pm.project_id
       WHERE pm.id = $1`,
      [person.id]
    )).rows[0];
    res.json({ success: true, person: internalPersonView(row) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.get('/api/bna/workspace-platform', requireAdmin, async (req, res) => {
  try {
    await ensureWorkspacePlatformDefaultsOnce();
    const requestedWorkspace = normalizeWorkspaceKey(req.query.workspace || req.query.workspace_key || '');
    const scopedWorkspace = opsScopeProjectKey(req) ? defaultWorkspaceKeyForRequest(req) : '';
    if (scopedWorkspace && requestedWorkspace && requestedWorkspace !== scopedWorkspace) assertWorkspaceAccess(req, requestedWorkspace);
    const workspaceFilter = scopedWorkspace || requestedWorkspace;
    if (workspaceFilter) assertWorkspaceAccess(req, workspaceFilter);

    const params = [];
    let workspaceQuery = `SELECT * FROM bna_workspace_settings WHERE status <> 'archived'`;
    if (workspaceFilter) {
      params.push(workspaceFilter);
      workspaceQuery += ` AND workspace_key = $${params.length}`;
    }
    workspaceQuery += ` ORDER BY CASE workspace_key WHEN 'platform' THEN 1 WHEN 'bna' THEN 2 WHEN 'rabbi_sheller_provider' THEN 3 ELSE 4 END, display_name ASC`;
    const workspaces = (await pool.query(workspaceQuery, params)).rows.map(workspaceView);

    const connectorParams = [];
    let connectorQuery = `SELECT * FROM bna_connector_settings`;
    if (workspaceFilter) {
      connectorParams.push(workspaceFilter);
      connectorQuery += ` WHERE workspace_key = $${connectorParams.length}`;
    }
    connectorQuery += ` ORDER BY workspace_key ASC, connector_type ASC, display_name ASC`;
    const connectorSettings = (await pool.query(connectorQuery, connectorParams)).rows.map(connectorSettingView);

    const logParams = [];
    let logQuery = `SELECT * FROM bna_bot_action_logs`;
    if (workspaceFilter) {
      logParams.push(workspaceFilter);
      logQuery += ` WHERE workspace_key = $${logParams.length}`;
    }
    logQuery += ` ORDER BY created_at DESC LIMIT 80`;
    const botActionLogs = (await pool.query(logQuery, logParams)).rows.map(botActionLogView);

    res.json({
      success: true,
      workspaces,
      connector_settings: connectorSettings,
      bot_actions: supportedBotActions(),
      bot_action_logs: botActionLogs,
      default_workspace: defaultWorkspaceKeyForRequest(req),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.get('/api/bna/learning-communities', requireAdmin, async (req, res) => {
  try {
    await ensureDefaultLearningCommunity();
    const requestedWorkspace = normalizeWorkspaceKey(req.query.workspace || req.query.workspace_key || '') || defaultWorkspaceKeyForRequest(req);
    const workspaceKey = assertWorkspaceAccess(req, requestedWorkspace);
    const result = await pool.query(
      `SELECT c.*,
              COUNT(DISTINCT m.id)::int AS member_count,
              COUNT(DISTINCT t.id)::int AS thread_count
       FROM bna_learning_communities c
       LEFT JOIN bna_learning_community_members m
         ON m.community_id = c.id
         AND m.status = 'active'
       LEFT JOIN bna_community_threads t
         ON t.community_id = c.id
         AND t.status <> 'archived'
       WHERE c.workspace_key = $1
         AND c.status <> 'archived'
       GROUP BY c.id
       ORDER BY c.updated_at DESC, c.id DESC`,
      [workspaceKey]
    );
    res.json({
      success: true,
      communities: result.rows.map((row) => ({
        ...learningCommunityView(row),
        member_count: Number(row.member_count || 0),
        thread_count: Number(row.thread_count || 0),
      })),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

