app.get('/api/bna/weekly-updates', requireAdmin, async (req, res) => {
  try {
    const workspaceKey = assertWorkspaceAccess(req, req.query.workspace || req.query.workspace_key || defaultWorkspaceKeyForRequest(req));
    const status = req.query.status ? safeWeeklyUpdateStatus(req.query.status, '') : '';
    const params = [workspaceKey];
    const conditions = [`workspace_key = $1`];
    if (status) {
      params.push(status);
      conditions.push(`status = $${params.length}`);
    } else {
      conditions.push(`status <> 'archived'`);
    }
    const result = await pool.query(
      `SELECT *
       FROM bna_weekly_updates
       WHERE ${conditions.join(' AND ')}
       ORDER BY selected_for_parent_portal DESC, week_start DESC NULLS LAST, created_at DESC, id DESC
       LIMIT 80`,
      params
    );
    res.json({ success: true, weekly_updates: result.rows.map(weeklyUpdateView) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

