app.patch('/api/bna/weekly-updates/:id', requireAdmin, async (req, res) => {
  try {
    const existing = (await pool.query('SELECT * FROM bna_weekly_updates WHERE id = $1', [req.params.id])).rows[0];
    if (!existing) return res.status(404).json({ error: 'Weekly update not found' });
    assertWorkspaceAccess(req, existing.workspace_key);
    const body = req.body || {};
    const fields = [];
    const values = [];
    const setField = (column, value, cast = '') => {
      values.push(value);
      fields.push(`${column} = $${values.length}${cast}`);
    };
    if (body.title !== undefined) setField('title', limitText(body.title, 220) || existing.title);
    if (body.title_he !== undefined) setField('title_he', limitText(body.title_he, 220) || null);
    if (body.summary !== undefined || body.excerpt !== undefined) setField('summary', limitText(body.summary || body.excerpt || '', 2200) || null);
    if (body.summary_he !== undefined || body.excerpt_he !== undefined) setField('summary_he', limitText(body.summary_he || body.excerpt_he || '', 2200) || null);
    if (body.body !== undefined || body.content !== undefined) setField('body', limitText(body.body || body.content || '', 12000) || null);
    if (body.body_he !== undefined || body.content_he !== undefined) setField('body_he', limitText(body.body_he || body.content_he || '', 12000) || null);
    if (body.week_start !== undefined || body.date !== undefined) setField('week_start', safeIsoDateInput(body.week_start || body.date) || null, '::date');
    if (body.image_url !== undefined || body.thumbnail_url !== undefined) setField('image_url', limitText(body.image_url || body.thumbnail_url || '', 1200) || null);
    if (body.video_url !== undefined || body.recording_url !== undefined || body.youtube_url !== undefined) setField('video_url', limitText(body.video_url || body.recording_url || body.youtube_url || '', 1200) || null);
    if (body.learned !== undefined) setField('learned_json', JSON.stringify(Array.isArray(body.learned) ? body.learned : []), '::jsonb');
    if (body.questions !== undefined) setField('questions_json', JSON.stringify(Array.isArray(body.questions) ? body.questions : []), '::jsonb');
    if (body.worksheets !== undefined) setField('worksheets_json', JSON.stringify(Array.isArray(body.worksheets) ? body.worksheets : []), '::jsonb');
    if (body.media !== undefined) setField('media_json', JSON.stringify(body.media && typeof body.media === 'object' ? body.media : {}), '::jsonb');
    if (body.metadata !== undefined) setField('metadata_json', JSON.stringify(body.metadata && typeof body.metadata === 'object' ? body.metadata : {}), '::jsonb');
    if (body.status !== undefined) setField('status', safeWeeklyUpdateStatus(body.status, existing.status));
    if (body.selected_for_parent_portal !== undefined || body.selected !== undefined) {
      const selected = Boolean(body.selected_for_parent_portal ?? body.selected);
      if (selected) {
        await pool.query(
          `UPDATE bna_weekly_updates
           SET selected_for_parent_portal = FALSE,
               updated_at = NOW()
           WHERE workspace_key = $1
             AND id <> $2`,
          [existing.workspace_key, existing.id]
        );
      }
      setField('selected_for_parent_portal', selected);
      if (selected && body.status === undefined) setField('status', 'selected');
    }
    if (!fields.length) return res.status(400).json({ error: 'No supported weekly update fields supplied' });
    values.push(req.params.id);
    const result = await pool.query(
      `UPDATE bna_weekly_updates
       SET ${fields.join(', ')},
           updated_at = NOW()
       WHERE id = $${values.length}
       RETURNING *`,
      values
    );
    res.json({ success: true, weekly_update: weeklyUpdateView(result.rows[0]) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

