app.patch('/api/bna/workspace-settings/:workspaceKey', requireAdmin, async (req, res) => {
  try {
    await ensureWorkspacePlatformDefaultsOnce();
    const workspaceKey = assertWorkspaceAccess(req, req.params.workspaceKey);
    const fields = [];
    const values = [];
    const body = req.body || {};

    if (body.display_name !== undefined) {
      values.push(limitText(body.display_name, 160));
      fields.push(`display_name = $${values.length}`);
    }
    if (body.description !== undefined) {
      values.push(limitText(body.description, 1200) || null);
      fields.push(`description = $${values.length}`);
    }
    if (body.status !== undefined) {
      const status = ['active', 'paused', 'archived'].includes(String(body.status || '')) ? String(body.status) : 'active';
      values.push(status);
      fields.push(`status = $${values.length}`);
    }
    if (body.owner_name !== undefined) {
      values.push(limitText(body.owner_name, 160) || null);
      fields.push(`owner_name = $${values.length}`);
    }
    if (body.settings !== undefined || body.settings_json !== undefined) {
      const settings = body.settings !== undefined ? body.settings : body.settings_json;
      values.push(JSON.stringify(settings && typeof settings === 'object' ? settings : {}));
      fields.push(`settings_json = COALESCE(settings_json, '{}'::jsonb) || $${values.length}::jsonb`);
    }
    if (!fields.length) return res.status(400).json({ error: 'No supported workspace settings supplied' });

    values.push(workspaceKey);
    const result = await pool.query(
      `UPDATE bna_workspace_settings
       SET ${fields.join(', ')},
           updated_at = NOW()
       WHERE workspace_key = $${values.length}
       RETURNING *`,
      values
    );
    if (!result.rows[0]) return res.status(404).json({ error: 'Workspace settings not found' });
    res.json({ success: true, workspace: workspaceView(result.rows[0]) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.get('/api/bna/connector-settings', requireAdmin, async (req, res) => {
  try {
    await ensureWorkspacePlatformDefaultsOnce();
    const requestedWorkspace = normalizeWorkspaceKey(req.query.workspace || req.query.workspace_key || '');
    const scopedWorkspace = opsScopeProjectKey(req) ? defaultWorkspaceKeyForRequest(req) : '';
    if (scopedWorkspace && requestedWorkspace && requestedWorkspace !== scopedWorkspace) assertWorkspaceAccess(req, requestedWorkspace);
    const workspaceFilter = scopedWorkspace || requestedWorkspace;
    if (workspaceFilter) assertWorkspaceAccess(req, workspaceFilter);
    const params = [];
    let query = `SELECT * FROM bna_connector_settings`;
    if (workspaceFilter) {
      params.push(workspaceFilter);
      query += ` WHERE workspace_key = $${params.length}`;
    }
    query += ` ORDER BY workspace_key ASC, connector_type ASC, display_name ASC`;
    const result = await pool.query(query, params);
    res.json({ success: true, connector_settings: result.rows.map(connectorSettingView) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.patch('/api/bna/connector-settings/:id', requireAdmin, async (req, res) => {
  try {
    await ensureWorkspacePlatformDefaultsOnce();
    const existing = (await pool.query('SELECT * FROM bna_connector_settings WHERE id = $1', [req.params.id])).rows[0];
    if (!existing) return res.status(404).json({ error: 'Connector setting not found' });
    assertWorkspaceAccess(req, existing.workspace_key);

    const fields = [];
    const values = [];
    const body = req.body || {};
    if (body.display_name !== undefined) {
      values.push(limitText(body.display_name, 180) || existing.display_name);
      fields.push(`display_name = $${values.length}`);
    }
    if (body.connector_type !== undefined) {
      values.push(safeConnectorType(body.connector_type));
      fields.push(`connector_type = $${values.length}`);
    }
    if (body.status !== undefined) {
      values.push(safeConnectorStatus(body.status, existing.status || 'not_configured'));
      fields.push(`status = $${values.length}`);
    }
    if (body.config !== undefined || body.config_json !== undefined) {
      const config = body.config !== undefined ? body.config : body.config_json;
      values.push(JSON.stringify(config && typeof config === 'object' ? config : {}));
      fields.push(`config_json = COALESCE(config_json, '{}'::jsonb) || $${values.length}::jsonb`);
    }
    if (body.metadata !== undefined || body.metadata_json !== undefined) {
      const metadata = body.metadata !== undefined ? body.metadata : body.metadata_json;
      values.push(JSON.stringify(metadata && typeof metadata === 'object' ? metadata : {}));
      fields.push(`metadata_json = COALESCE(metadata_json, '{}'::jsonb) || $${values.length}::jsonb`);
    }
    if (!fields.length) return res.status(400).json({ error: 'No supported connector setting fields supplied' });

    values.push(req.opsUser || 'admin');
    fields.push(`updated_by = $${values.length}`);
    values.push(req.params.id);
    const result = await pool.query(
      `UPDATE bna_connector_settings
       SET ${fields.join(', ')},
           updated_at = NOW()
       WHERE id = $${values.length}
       RETURNING *`,
      values
    );
    res.json({ success: true, connector_setting: connectorSettingView(result.rows[0]) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

