app.get('/api/bna/actions/audit-log', requireAdmin, async (req, res) => {
  try {
    const requestedWorkspace = normalizeWorkspaceKey(req.query.workspace || req.query.workspace_key || '');
    const workspaceKey = requestedWorkspace || defaultWorkspaceKeyForRequest(req);
    if (workspaceKey) assertWorkspaceAccess(req, workspaceKey);
    const limit = Math.max(1, Math.min(Number(req.query.limit || 100), 300));
    let logs = [];
    try {
      const params = [];
      const conditions = [];
      if (workspaceKey) {
        params.push(workspaceKey);
        conditions.push(`workspace_key = $${params.length}`);
      }
      params.push(limit);
      const result = await pool.query(
        `SELECT *
         FROM bna_bot_action_logs
         ${conditions.length ? `WHERE ${conditions.join(' AND ')}` : ''}
         ORDER BY created_at DESC, id DESC
         LIMIT $${params.length}`,
        params
      );
      logs = result.rows.map(botActionLogView);
    } catch {
      logs = [];
    }
    res.json({
      success: true,
      logs,
      in_memory_runs: listInMemoryActionRuns().slice(-limit).reverse(),
    });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

