app.patch('/api/bna/support-tickets/:id', requireAdmin, async (req, res) => {
  const allowedFields = ['title', 'description', 'severity', 'status', 'category', 'assigned_to', 'reporter_name', 'reporter_role', 'related_task_id', 'source_context'];
  const fields = [];
  const values = [];
  const body = req.body || {};
  let statusParamIndex = null;
  for (const field of allowedFields) {
    if (!Object.prototype.hasOwnProperty.call(body, field)) continue;
    let value = body[field];
    if (field === 'severity') value = safeSupportTicketSeverity(value);
    if (field === 'status') value = safeSupportTicketStatus(value);
    if (field === 'category') value = safeSupportTicketCategory(value);
    if (field === 'source_context') value = JSON.stringify(value || {});
    values.push(value === undefined || value === '' ? null : value);
    if (field === 'status') statusParamIndex = values.length;
    fields.push(`${field} = $${values.length}`);
  }
  if (statusParamIndex) {
    fields.push(`resolved_at = CASE WHEN $${statusParamIndex} IN ('resolved', 'closed') THEN COALESCE(resolved_at, NOW()) ELSE NULL END`);
  }
  if (!fields.length) return res.status(400).json({ error: 'No supported ticket fields supplied' });
  values.push(req.params.id);
  try {
    await assertSupportTicketAccess(req, req.params.id);
    const result = await pool.query(
      `UPDATE bna_support_tickets
       SET ${fields.join(', ')},
           updated_at = NOW()
       WHERE id = $${values.length}
       RETURNING *`,
      values
    );
    if (!result.rows[0]) return res.status(404).json({ error: 'Support ticket not found' });
    res.json({ success: true, ticket: supportTicketView(result.rows[0]) });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

