function isTaskCommentRequeueOptOut(value) {
  if (value === false || value === 0) return true;
  return /^(?:false|no|off|0)$/i.test(String(value || '').trim());
}

function shouldRequeueTaskAfterHumanComment({ source, author, requeue } = {}) {
  if (isTaskCommentRequeueOptOut(requeue)) return false;
  const normalizedSource = String(source || '').trim().toLowerCase();
  if (!['dashboard', 'telegram', 'api'].includes(normalizedSource)) return false;
  const actor = String(author || '').trim().toLowerCase();
  if (/\b(agent|agent-fleet|codex|kimi|watchdog|system|smoke|railway|automation|bot)\b/.test(actor)) return false;
  return true;
}

app.post('/api/bna/tasks/:id/comments', requireAdmin, async (req, res) => {
  const body = String(req.body?.body || req.body?.comment || '').trim();
  if (!body) return res.status(400).json({ error: 'Comment body is required' });
  try {
    await assertTaskAccess(req, req.params.id);
    const author = String(req.body?.author || req.opsUser || 'dashboard').slice(0, 120);
    const visibility = ['internal', 'operator', 'project'].includes(req.body?.visibility) ? req.body.visibility : 'internal';
    const source = ['dashboard', 'telegram', 'api', 'system'].includes(req.body?.source) ? req.body.source : 'dashboard';
    const result = await pool.query(
      `INSERT INTO bna_task_comments (task_id, author, body, visibility, source, source_context)
       VALUES ($1, $2, $3, $4, $5, $6)
       RETURNING *`,
      [
        req.params.id,
        author,
        body,
        visibility,
        source,
        JSON.stringify(req.body?.source_context || {}),
      ]
    );
    let task = null;
    const requeue = shouldRequeueTaskAfterHumanComment({ source, author, requeue: req.body?.requeue });
    if (requeue) {
      const taskResult = await pool.query(
        `UPDATE bna_tasks
         SET stage = 'assigned',
             assigned_to = 'Codex',
             decision_required = FALSE,
             started_at = NULL,
             completed_at = NULL,
             archived_at = NULL,
             verified_at = NULL,
             verification_notes = $2,
             updated_at = NOW()
         WHERE id = $1
         RETURNING *`,
        [
          req.params.id,
          `Requeued after operator comment at ${new Date().toISOString()}.`,
        ]
      );
      task = taskResult.rows[0] || null;
    }
    res.json({ success: true, comment: result.rows[0], requeued: Boolean(task), task });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

app.patch('/api/bna/tasks/:id', requireAdmin, async (req, res) => {
  const { id } = req.params;
  const updates = req.body;
  
  const fields = [];
  const values = [];
  let idx = 1;
  
  const allowedFields = new Set([
    'title',
    'notes',
    'stage',
    'category',
    'urgency',
    'energy_required',
    'estimated_minutes',
    'due_date',
    'planned_at',
    'started_at',
    'completed_at',
    'archived_at',
    'assigned_to',
    'verified_at',
    'verification_notes',
    'decision_required',
    'author',
  ]);
  try {
    await assertTaskAccess(req, id);
    for (const [key, value] of Object.entries(updates)) {
      if (key === 'project' || key === 'project_key' || key === 'project_id') {
        const project = await resolveProjectFromInput({ [key]: value }, pool);
        assertProjectAccess(req, project);
        fields.push(`project_id = $${idx++}`);
        values.push(project.id);
        continue;
      }
      if (!allowedFields.has(key)) continue;
      const nextValue = key === 'assigned_to'
        ? normalizeTaskAssignee(value)
        : key === 'category'
          ? safeTaskCategory(value)
          : value;
      fields.push(`${key} = $${idx++}`);
      values.push(nextValue);
    }
    if (!fields.length) return res.status(400).json({ error: 'No allowed task fields supplied' });
    fields.push('updated_at = NOW()');
    values.push(id);

    const result = await pool.query(
      `UPDATE bna_tasks SET ${fields.join(', ')} WHERE id = $${idx} RETURNING *`,
      values
    );
    res.json({ success: true, task: result.rows[0] });
  } catch (err) {
    res.status(err.statusCode || 500).json({ error: err.message });
  }
});

